// Bai tap ngu phap hsk3 — soan rieng theo trinh do (sinh tu data-grammar/hsk3/).
window.GRAMMAR_EXTRA = Object.assign(window.GRAMMAR_EXTRA || {}, {"/lessons/hsk3-bai-1.html":[{"point":"Bổ ngữ kết quả 「好」","items":[{"context":"“Vé xem phim đã mua xong rồi.”","pre":"电影票已经","blank":"买好","post":"了。","options":["买好","好买","买得好"],"answer":0,"explanation":"好 đứng NGAY SAU động từ: 买 + 好 = mua xong và ổn thoả."},{"context":"“Cơm vẫn chưa nấu xong.”","pre":"饭还","blank":"没做好","post":"。","options":["没做好","没做好了","不做好"],"answer":0,"explanation":"Phủ định dùng 没 + V + 好, KHÔNG kèm 了."},{"context":"“Đồ đi du lịch chuẩn bị xong chưa?”","pre":"去旅游的东西","blank":"准备好","post":"了吗？","options":["准备好","好准备","准备着"],"answer":0,"explanation":"准备好 = chuẩn bị xong xuôi, sẵn sàng."},{"context":"“Tôi đã nghĩ kỹ rồi.”","pre":"我早就","blank":"想好","post":"了。","options":["想好","好想","想得好"],"answer":0,"explanation":"想好 = nghĩ xong, đã quyết."},{"context":"Nhấn mạnh chỉ “làm hết, kết thúc” (không kèm ý hài lòng) thì dùng 完.","pre":"这本书我已经看","blank":"完","post":"了。","options":["完","好","着"],"answer":0,"explanation":"看完 = đọc hết; 看好 nghe không tự nhiên với sách."},{"context":"“Bàn ghế đã kê xong rồi.”","pre":"桌子椅子都","blank":"放好","post":"了。","options":["放好","好放","放完好"],"answer":0,"explanation":"放好 = đặt đâu vào đấy."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我早就好想了。","isCorrect":false,"correctVersion":"我早就想好了。","explanation":"Bổ ngữ kết quả 好 phải đứng SAU động từ 想."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"电影票买好了吗？","isCorrect":true,"explanation":"V + 好 + 了 + 吗 hỏi việc đã hoàn thành ổn thoả chưa."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"饭还没做好了。","isCorrect":false,"correctVersion":"饭还没做好。","explanation":"没 và 了 không dùng cùng nhau."},{"type":"sort","context":"Sắp xếp: “Những thứ này hôm qua tôi đã chuẩn bị xong.”","words":["这些","我","昨天","就","准备","好","了","。"],"answer":"这些我昨天就准备好了。","explanation":"就 nhấn mạnh sớm; 准备好了 = V + 好 + 了."},{"type":"sort","context":"Sắp xếp: “Mẹ đã nấu xong bữa tối.”","words":["妈妈","已经","做好","晚饭","了","。"],"answer":"妈妈已经做好晚饭了。","explanation":"做好 + tân ngữ + 了."},{"type":"sort","context":"Sắp xếp: “Bạn nghĩ kỹ chưa, có đi cùng tôi không?”","words":["你","想好","了","吗","，","跟","我","一起","去","？"],"answer":"你想好了吗，跟我一起去？","explanation":"想好了吗 = đã quyết chưa."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ kết quả 好.","promptLang":"vi","prompt":"Bài tập của tôi đã làm xong rồi.","answer":"我的作业写好了。","answerPy":"Wǒ de zuòyè xiěhǎo le.","explanation":"写 + 好 + 了 = viết xong xuôi."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ kết quả 好.","promptLang":"vi","prompt":"Cơm vẫn chưa nấu xong, đợi một lát nhé.","answer":"饭还没做好，请等一会儿。","answerPy":"Fàn hái méi zuòhǎo, qǐng děng yíhuìr.","explanation":"没 + V + 好, không dùng 了."}]},{"point":"「一……也/都 + 不/没……」 — phủ định hoàn toàn","items":[{"context":"“Tôi không quen một ai cả.”","pre":"我","blank":"一个人也不","post":"认识。","options":["一个人也不","一个人不也","也一个人不"],"answer":0,"explanation":"一 + lượng từ + danh từ + 也/都 + 不/没."},{"context":"“Anh ấy chẳng ăn chút cơm nào.”","pre":"他","blank":"一点儿饭也没","post":"吃。","options":["一点儿饭也没","一点儿也饭没","没一点儿饭也"],"answer":0,"explanation":"Việc đã xảy ra dùng 没; 也 ngay trước 没."},{"context":"“Tôi một câu cũng không muốn nói.”","pre":"我","blank":"一句话也不","post":"想说。","options":["一句话也不","也一句话不","一句话不也"],"answer":0,"explanation":"也 luôn đứng ngay trước phần phủ định."},{"context":"Có thể thay 也 bằng 都.","pre":"这些菜我","blank":"一个都没","post":"吃。","options":["一个都没","都一个没","一个没都"],"answer":0,"explanation":"都 dùng như 也 trong khung phủ định hoàn toàn."},{"context":"“Hôm nay tôi chẳng bận chút nào.”","pre":"今天我","blank":"一点儿也不","post":"忙。","options":["一点儿也不","一点也不儿","不一点儿也"],"answer":0,"explanation":"一点儿也不 + tính từ."},{"context":"“Tiền tôi một xu cũng không có.”","pre":"我","blank":"一分钱也没","post":"有。","options":["一分钱也没","一分也钱没","没一分钱也"],"answer":0,"explanation":"Khung này rất hay gặp khi nhấn mạnh “không hề”."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我一个人不认识。","isCorrect":false,"correctVersion":"我一个人也不认识。","explanation":"Thiếu 也/都 thì khung phủ định hoàn toàn không thành lập."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他一点儿饭也没吃。","isCorrect":true,"explanation":"Đúng khung: 一点儿 + danh từ + 也 + 没 + động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我也一句话不想说。","isCorrect":false,"correctVersion":"我一句话也不想说。","explanation":"也 phải đứng ngay trước 不/没, không đứng sau chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Ở đây tôi không quen một ai cả.”","words":["在","这儿","我","一个人","也","不","认识","。"],"answer":"在这儿我一个人也不认识。","explanation":"Nơi chốn đầu câu, khung phủ định ở vị ngữ."},{"type":"sort","context":"Sắp xếp: “Hôm qua anh ấy chẳng ăn chút gì.”","words":["昨天","他","一点儿","东西","也","没","吃","。"],"answer":"昨天他一点儿东西也没吃。","explanation":"Việc đã qua dùng 没."},{"type":"sort","context":"Sắp xếp: “Mấy quyển sách này tôi chưa đọc quyển nào.”","words":["这些","书","我","一","本","都","没","看","。"],"answer":"这些书我一本都没看。","explanation":"一 + 本 + 都 + 没 + động từ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng khung 一……也/都 + 不/没.","promptLang":"vi","prompt":"Tôi chẳng quen một ai ở đây cả.","answer":"我一个人也不认识。","answerPy":"Wǒ yí ge rén yě bú rènshi.","explanation":"Khung phủ định hoàn toàn."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng khung 一……也/都 + 不/没.","promptLang":"vi","prompt":"Hôm nay tôi chẳng bận chút nào.","answer":"今天我一点儿也不忙。","answerPy":"Jīntiān wǒ yìdiǎnr yě bù máng.","explanation":"一点儿也不 + tính từ."}]},{"point":"Liên từ 「那」 đứng đầu câu (vậy thì)","items":[{"context":"Bạn nói bận sáng, em đề nghị buổi chiều.","pre":"","blank":"那","post":"我们下午去吧。","options":["那","就","还"],"answer":0,"explanation":"那 đứng đầu câu, nối tiếp điều người kia vừa nói."},{"context":"“Vậy thì 8 giờ gặp nhé.”","pre":"","blank":"那","post":"我们八点见吧。","options":["那","那么什么","还是那"],"answer":0,"explanation":"Khẩu ngữ dùng 那 gọn, tự nhiên."},{"context":"“Bạn không đi, vậy tôi cũng không đi.”","pre":"你不去，","blank":"那","post":"我也不去。","options":["那","就","才"],"answer":0,"explanation":"那 đứng đầu VẾ SAU, sau khi đã có tiền đề."},{"context":"“Vậy bạn muốn ăn gì?”","pre":"","blank":"那","post":"你想吃什么？","options":["那","还","就"],"answer":0,"explanation":"那 mở đầu câu hỏi tiếp nối."},{"context":"“Vậy để mai nói tiếp.”","pre":"","blank":"那","post":"明天再说吧。","options":["那","又","才"],"answer":0,"explanation":"那 + đề nghị mới dựa trên tình hình vừa biết."},{"context":"“Hôm nay mưa. Vậy chúng ta ở nhà vậy.”","pre":"今天下雨了。","blank":"那","post":"我们在家吧。","options":["那","就是","还是那么"],"answer":0,"explanation":"那 nối hai lượt lời một cách tự nhiên."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们那八点见吧。","isCorrect":false,"correctVersion":"那我们八点见吧。","explanation":"那 (liên từ) đứng ĐẦU câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你很忙，那我自己去。","isCorrect":true,"explanation":"Có tiền đề ở vế trước, 那 mở đầu vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"那你想吃什么？","isCorrect":true,"explanation":"那 mở đầu câu hỏi tiếp nối lời người kia."},{"type":"sort","context":"Sắp xếp: “Vậy chiều nay chúng ta đi nhé.”","words":["那","我们","下午","去","吧","。"],"answer":"那我们下午去吧。","explanation":"那 + chủ ngữ + thời gian + động từ + 吧."},{"type":"sort","context":"Sắp xếp: “Bạn không thích, vậy tôi đổi cái khác.”","words":["你","不","喜欢","，","那","我","换","一个","。"],"answer":"你不喜欢，那我换一个。","explanation":"那 mở đầu vế sau."},{"type":"sort","context":"Sắp xếp: “Vậy để mai nói tiếp nhé.”","words":["那","明天","再","说","吧","。"],"answer":"那明天再说吧。","explanation":"再 = rồi hãy, đứng trước động từ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng liên từ 那.","promptLang":"vi","prompt":"Bạn bận à? Vậy chúng ta gặp nhau ngày mai nhé.","answer":"你很忙吗？那我们明天见吧。","answerPy":"Nǐ hěn máng ma? Nà wǒmen míngtiān jiàn ba.","explanation":"那 nối lượt lời, 吧 làm lời đề nghị."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng liên từ 那.","promptLang":"vi","prompt":"Trời mưa rồi, vậy chúng ta ở nhà đi.","answer":"下雨了，那我们在家吧。","answerPy":"Xià yǔ le, nà wǒmen zài jiā ba.","explanation":"Tiền đề trước, 那 mở đầu đề nghị."}]}],"/lessons/hsk3-bai-2.html":[{"point":"Bổ ngữ xu hướng đơn 「V + 来 / 去」","items":[{"context":"Em đang ở trong phòng, thầy bước vào.","pre":"老师","blank":"进来","post":"了。","options":["进来","进去","来进"],"answer":0,"explanation":"Hướng về PHÍA người nói dùng 来."},{"context":"Em đang ở ngoài, nhìn bạn bước vào phòng.","pre":"他","blank":"进去","post":"了。","options":["进去","进来","去进"],"answer":0,"explanation":"Hướng RỜI XA người nói dùng 去."},{"context":"“Anh ấy về nhà rồi.” (người nói ở nhà)","pre":"他","blank":"回家来","post":"了。","options":["回家来","回来家","来回家"],"answer":0,"explanation":"Tân ngữ nơi chốn đứng GIỮA: 回 + 家 + 来."},{"context":"“Bạn mang quyển sách lên đây nhé.”","pre":"你把书","blank":"拿上来","post":"。","options":["拿上来","上拿来","拿来上"],"answer":0,"explanation":"Động từ + hướng (上) + 来."},{"context":"“Mời vào.”","pre":"请","blank":"进来","post":"。","options":["进来","进来去","来进去"],"answer":0,"explanation":"Chủ nhà mời khách vào chỗ mình → 来."},{"context":"“Bạn ấy chạy ra ngoài rồi.” (người nói ở trong)","pre":"她","blank":"跑出去","post":"了。","options":["跑出去","跑出来","出跑去"],"answer":0,"explanation":"Ra xa người nói → 去."},{"type":"judge","context":"Xét câu sau đúng hay sai (người nói đang ở trong lớp).","sentence":"老师进去了。","isCorrect":false,"correctVersion":"老师进来了。","explanation":"Người nói ở trong thì hướng vào là 来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他回来家了。","isCorrect":false,"correctVersion":"他回家来了。","explanation":"Tân ngữ nơi chốn chen vào giữa động từ và 来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"请进来吧。","isCorrect":true,"explanation":"Lời mời vào chỗ người nói."},{"type":"sort","context":"Sắp xếp: “Thầy giáo bước vào lớp rồi.” (em ở trong lớp)","words":["老师","走","进","教室","来","了","。"],"answer":"老师走进教室来了。","explanation":"V + 进 + nơi chốn + 来."},{"type":"sort","context":"Sắp xếp: “Bạn ấy mang một quyển sách đến.”","words":["她","拿","来","了","一","本","书","。"],"answer":"她拿来了一本书。","explanation":"Tân ngữ chỉ vật có thể đứng sau 来了."},{"type":"sort","context":"Sắp xếp: “Mẹ tôi về nhà rồi.”","words":["我","妈妈","回","家","来","了","。"],"answer":"我妈妈回家来了。","explanation":"回 + 家 + 来."},{"type":"translate","context":"Dịch sang tiếng Trung (em đang ở trong phòng).","promptLang":"vi","prompt":"Mời thầy vào ạ.","answer":"老师，请进来。","answerPy":"Lǎoshī, qǐng jìnlái.","explanation":"Hướng về phía người nói dùng 来."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy chạy ra ngoài rồi.","answer":"他跑出去了。","answerPy":"Tā pǎo chūqù le.","explanation":"Rời xa người nói dùng 去."}]},{"point":"Hai hành động liên tiếp 「V了……就V……」","items":[{"context":"“Tôi ăn cơm xong là đi học ngay.”","pre":"我","blank":"吃了饭就","post":"去学校。","options":["吃了饭就","吃饭了就","就吃了饭"],"answer":0,"explanation":"V + 了 + tân ngữ + 就 + V."},{"context":"“Tan học xong tôi về nhà luôn.”","pre":"我","blank":"下了课就","post":"回家。","options":["下了课就","下课了就","就下了课"],"answer":0,"explanation":"了 đi liền sau động từ thứ nhất."},{"context":"Nhấn mạnh việc xảy ra MUỘN thì dùng 才.","pre":"他昨天十一点","blank":"才","post":"回家。","options":["才","就","还"],"answer":0,"explanation":"才 = mãi mới; 就 = ngay lập tức."},{"context":"“Mua xong đồ là tôi về ngay.”","pre":"我","blank":"买了东西就","post":"回来。","options":["买了东西就","买东西了就","就买了东西"],"answer":0,"explanation":"Khung V了…就V… diễn tả hai việc nối tiếp nhanh."},{"context":"Kế hoạch tương lai: vế sau KHÔNG dùng 了.","pre":"明天我下了班就","blank":"去","post":"你家。","options":["去","去了","了去"],"answer":0,"explanation":"Việc chưa xảy ra thì không dùng 了 ở vế sau."},{"context":"“Nghe xong là hiểu ngay.”","pre":"我","blank":"听了就","post":"明白了。","options":["听了就","听就了","就听了"],"answer":0,"explanation":"V了 + 就 + kết quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我吃饭了就去学校。","isCorrect":false,"correctVersion":"我吃了饭就去学校。","explanation":"了 phải đứng ngay sau động từ 吃."},{"type":"judge","context":"Xét câu sau đúng hay sai (nói về kế hoạch ngày mai).","sentence":"明天我下了课就去图书馆。","isCorrect":true,"explanation":"Vế sau chỉ việc chưa xảy ra, không dùng 了 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai (ý: ăn xong đi ngay).","sentence":"我吃了饭才去学校。","isCorrect":false,"correctVersion":"我吃了饭就去学校。","explanation":"才 mang nghĩa muộn, ngược với ý “ngay”."},{"type":"sort","context":"Sắp xếp: “Tôi ăn cơm xong là đi học ngay.”","words":["我","吃","了","饭","就","去","学校","。"],"answer":"我吃了饭就去学校。","explanation":"V + 了 + O + 就 + V."},{"type":"sort","context":"Sắp xếp: “Tan làm xong tôi đến nhà bạn ngay.”","words":["我","下","了","班","就","去","你","家","。"],"answer":"我下了班就去你家。","explanation":"下了班 = tan làm xong."},{"type":"sort","context":"Sắp xếp: “Anh ấy về đến nhà là ngủ luôn.”","words":["他","回","了","家","就","睡觉","了","。"],"answer":"他回了家就睡觉了。","explanation":"Việc đã xảy ra thì vế sau có thể có 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng khung V了……就……","promptLang":"vi","prompt":"Tôi ăn cơm xong là đi làm ngay.","answer":"我吃了饭就去上班。","answerPy":"Wǒ chī le fàn jiù qù shàngbān.","explanation":"了 liền sau 吃, 就 trước động từ thứ hai."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng khung V了……就……","promptLang":"vi","prompt":"Ngày mai tan học xong tôi sẽ đến tìm bạn.","answer":"明天我下了课就去找你。","answerPy":"Míngtiān wǒ xià le kè jiù qù zhǎo nǐ.","explanation":"Kế hoạch tương lai, vế sau không có 了."}]},{"point":"Câu phản vấn 「能……吗？」","items":[{"context":"“Chuyện này làm sao mà không làm được?” (ý: nhất định phải làm)","pre":"这个事情","blank":"能不做","post":"吗？","options":["能不做","能不能做","不能做不"],"answer":0,"explanation":"能 + 不 + V + 吗 = câu phản vấn, khẳng định mạnh."},{"context":"“Tôi làm sao không giúp bạn được?” (nhất định giúp)","pre":"我","blank":"能不帮","post":"你吗？","options":["能不帮","不能帮","能帮不"],"answer":0,"explanation":"Hình thức hỏi nhưng ý là khẳng định."},{"context":"Câu hỏi THẬT (xin phép) thì dùng 能…吗.","pre":"我","blank":"能","post":"用一下你的电脑吗？","options":["能","能不","不能"],"answer":0,"explanation":"能…吗 hỏi xin phép; 能不…吗 mới là phản vấn."},{"context":"“Chuyện quan trọng thế, sao có thể quên được?”","pre":"这么重要的事，我","blank":"能忘","post":"吗？","options":["能忘","不能忘","能不忘"],"answer":0,"explanation":"能 + V + 吗 cũng dùng phản vấn khi ngữ cảnh rõ: “sao quên được”."},{"context":"“Bạn ốm thế này, làm sao đi làm được?”","pre":"你病了，","blank":"能去","post":"上班吗？","options":["能去","能不去","不能去"],"answer":0,"explanation":"Câu phản vấn phủ định ý “đi làm”."},{"context":"“Việc này ai mà không biết?”","pre":"这件事，谁","blank":"不知道","post":"呢？","options":["不知道","知道不","能知道"],"answer":0,"explanation":"谁不…呢 cũng là khung phản vấn quen thuộc."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个事情能不能不做吗？","isCorrect":false,"correctVersion":"这个事情能不做吗？","explanation":"Không dùng đồng thời mẫu chính phản và 吗."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我能不帮你吗？","isCorrect":true,"explanation":"Câu phản vấn: hình thức hỏi, ý khẳng định “chắc chắn giúp”."},{"type":"judge","context":"Xét câu sau đúng hay sai (ý xin phép mượn máy tính).","sentence":"我能用一下你的电脑吗？","isCorrect":true,"explanation":"能…吗 dùng để xin phép, hoàn toàn đúng."},{"type":"sort","context":"Sắp xếp: “Chuyện quan trọng thế, tôi sao quên được?”","words":["这么","重要","的","事","，","我","能","忘","吗","？"],"answer":"这么重要的事，我能忘吗？","explanation":"Câu phản vấn nhấn mạnh “không thể quên”."},{"type":"sort","context":"Sắp xếp: “Bạn ốm rồi, sao còn đi làm được?”","words":["你","病","了","，","能","去","上班","吗","？"],"answer":"你病了，能去上班吗？","explanation":"Tiền đề + câu phản vấn."},{"type":"sort","context":"Sắp xếp: “Tôi có thể mượn quyển sách này không?”","words":["我","能","借","这","本","书","吗","？"],"answer":"我能借这本书吗？","explanation":"Câu hỏi xin phép thật sự."},{"type":"translate","context":"Dịch sang tiếng Trung bằng câu phản vấn.","promptLang":"vi","prompt":"Bạn ốm thế này, làm sao mà đi làm được?","answer":"你病成这样，能去上班吗？","answerPy":"Nǐ bìng chéng zhèyàng, néng qù shàngbān ma?","explanation":"Hình thức hỏi nhưng ý phủ định."},{"type":"translate","context":"Dịch sang tiếng Trung bằng câu phản vấn.","promptLang":"vi","prompt":"Bạn nhờ rồi, tôi làm sao mà không giúp được?","answer":"你说了，我能不帮你吗？","answerPy":"Nǐ shuō le, wǒ néng bù bāng nǐ ma?","explanation":"能不 + V + 吗 = nhất định sẽ làm."}]}],"/lessons/hsk3-bai-3.html":[{"point":"「还是」và「或者」— HAY / HOẶC","items":[{"context":"Câu HỎI lựa chọn: “Bạn uống trà hay cà phê?”","pre":"你喝茶","blank":"还是","post":"喝咖啡？","options":["还是","或者","和"],"answer":0,"explanation":"还是 dùng trong câu hỏi lựa chọn."},{"context":"Câu TRẦN THUẬT: “Trà hoặc cà phê đều được.”","pre":"茶","blank":"或者","post":"咖啡都可以。","options":["或者","还是","也"],"answer":0,"explanation":"或者 dùng trong câu kể."},{"context":"“Bạn muốn đi Bắc Kinh hay Thượng Hải?”","pre":"你想去北京","blank":"还是","post":"上海？","options":["还是","或者","以及"],"answer":0,"explanation":"Hai lựa chọn trong câu hỏi."},{"context":"“Cuối tuần tôi thường đọc sách hoặc xem phim.”","pre":"周末我常常看书","blank":"或者","post":"看电影。","options":["或者","还是","又"],"answer":0,"explanation":"Câu kể về thói quen, dùng 或者."},{"context":"Câu hỏi có 还是 thì KHÔNG thêm 吗.","pre":"你今天去","blank":"还是明天去","post":"？","options":["还是明天去","还是明天去吗","或者明天去吗"],"answer":0,"explanation":"还是 đã tạo câu hỏi lựa chọn."},{"context":"“Ai đi cũng được, bạn hoặc tôi.”","pre":"你","blank":"或者","post":"我去都行。","options":["或者","还是","都"],"answer":0,"explanation":"Câu kể nêu hai khả năng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你喝茶或者喝咖啡？","isCorrect":false,"correctVersion":"你喝茶还是喝咖啡？","explanation":"Câu hỏi lựa chọn phải dùng 还是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"周末我看书或者看电影。","isCorrect":true,"explanation":"Câu kể dùng 或者 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我喝茶还是咖啡都可以。","isCorrect":false,"correctVersion":"我喝茶或者咖啡都可以。","explanation":"Câu trần thuật dùng 或者."},{"type":"sort","context":"Sắp xếp: “Bạn đi hôm nay hay ngày mai?”","words":["你","今天","去","还是","明天","去","？"],"answer":"你今天去还是明天去？","explanation":"还是 nối hai lựa chọn trong câu hỏi."},{"type":"sort","context":"Sắp xếp: “Cuối tuần tôi thường đọc sách hoặc nghe nhạc.”","words":["周末","我","常常","看书","或者","听音乐","。"],"answer":"周末我常常看书或者听音乐。","explanation":"或者 trong câu kể."},{"type":"sort","context":"Sắp xếp: “Bạn muốn ăn cơm hay ăn mì?”","words":["你","想","吃","米饭","还是","吃","面条","？"],"answer":"你想吃米饭还是吃面条？","explanation":"Câu hỏi lựa chọn."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn uống trà hay uống cà phê?","answer":"你喝茶还是喝咖啡？","answerPy":"Nǐ hē chá háishi hē kāfēi?","explanation":"Câu hỏi lựa chọn dùng 还是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thứ bảy hoặc chủ nhật tôi đều rảnh.","answer":"星期六或者星期日我都有时间。","answerPy":"Xīngqīliù huòzhě xīngqīrì wǒ dōu yǒu shíjiān.","explanation":"Câu kể dùng 或者, có 都 tổng kết."}]},{"point":"Câu tồn tại 「Nơi chốn + V着 + số lượng + danh từ」","items":[{"context":"“Trên bàn có đặt một quyển sách.”","pre":"桌子上","blank":"放着","post":"一本书。","options":["放着","放了","着放"],"answer":0,"explanation":"Nơi chốn + V着 + số lượng + danh từ."},{"context":"“Ngoài cửa đứng một người.”","pre":"门外","blank":"站着","post":"一个人。","options":["站着","站了","在站"],"answer":0,"explanation":"着 biểu thị trạng thái đang tồn tại."},{"context":"“Trên tường treo mấy bức ảnh.”","pre":"墙上","blank":"挂着","post":"几张照片。","options":["挂着","挂了","挂过"],"answer":0,"explanation":"Câu tồn tại với 着."},{"context":"“Cửa đang mở đấy.”","pre":"门","blank":"开着","post":"呢。","options":["开着","开了着","着开"],"answer":0,"explanation":"V着 + 呢 = trạng thái đang duy trì."},{"context":"“Trong phòng ngồi rất nhiều người.”","pre":"房间里","blank":"坐着","post":"很多人。","options":["坐着","坐了","在坐"],"answer":0,"explanation":"Nơi chốn đứng đầu câu tồn tại."},{"context":"Nhấn mạnh việc ĐÃ XẢY RA thì dùng 了.","pre":"他把书","blank":"放","post":"在桌子上了。","options":["放","放着","着放"],"answer":0,"explanation":"Câu nhấn mạnh hành động dùng 了; câu tả cảnh dùng 着."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"一本书放着桌子上。","isCorrect":false,"correctVersion":"桌子上放着一本书。","explanation":"Nơi chốn phải đứng ĐẦU câu tồn tại."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"门外站着一个人。","isCorrect":true,"explanation":"Đúng khung: nơi chốn + V着 + số lượng + danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"桌子上放了着一本书。","isCorrect":false,"correctVersion":"桌子上放着一本书。","explanation":"Không dùng 了 và 着 cùng lúc."},{"type":"sort","context":"Sắp xếp: “Trên bàn đặt hai quyển sách.”","words":["桌子","上","放","着","两","本","书","。"],"answer":"桌子上放着两本书。","explanation":"Nơi chốn + V着 + số lượng."},{"type":"sort","context":"Sắp xếp: “Ngoài cửa đứng mấy người.”","words":["门","外","站","着","几","个","人","。"],"answer":"门外站着几个人。","explanation":"几个人 = mấy người."},{"type":"sort","context":"Sắp xếp: “Trên tường treo một bức tranh.”","words":["墙","上","挂","着","一","张","画","。"],"answer":"墙上挂着一张画。","explanation":"挂着 = đang treo."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu tồn tại với 着.","promptLang":"vi","prompt":"Trên bàn đặt một chiếc máy tính.","answer":"桌子上放着一个电脑。","answerPy":"Zhuōzi shàng fàngzhe yí ge diànnǎo.","explanation":"Nơi chốn + 放着 + số lượng + vật."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu tồn tại với 着.","promptLang":"vi","prompt":"Ngoài cửa đứng một người.","answer":"门外站着一个人。","answerPy":"Mén wài zhànzhe yí ge rén.","explanation":"站着 = đang đứng."}]},{"point":"Trợ động từ 「会」 biểu thị khả năng sẽ xảy ra","items":[{"context":"“Ngày mai trời sẽ mưa.”","pre":"明天","blank":"会","post":"下雨。","options":["会","能","可以"],"answer":0,"explanation":"会 = khả năng sẽ xảy ra trong tương lai."},{"context":"“Anh ấy sẽ không đến đâu.”","pre":"他","blank":"不会","post":"来的。","options":["不会","没会","不能"],"answer":0,"explanation":"Phủ định là 不会; cuối câu hay thêm 的 để khẳng định."},{"context":"Hỏi chính phản: “Ngày mai trời có mưa không?”","pre":"明天","blank":"会不会","post":"下雨？","options":["会不会","会吗不","能不能"],"answer":0,"explanation":"会不会 + động từ."},{"context":"Nói về KỸ NĂNG học được cũng dùng 会.","pre":"我","blank":"会","post":"说一点儿汉语。","options":["会","能","要"],"answer":0,"explanation":"会 có hai nghĩa: biết làm và sẽ xảy ra."},{"context":"Nói về ĐIỀU KIỆN cho phép thì dùng 能.","pre":"明天我有事，不","blank":"能","post":"去。","options":["能","会","可以吗"],"answer":0,"explanation":"不能去 = bận nên không đi được; 不会去 = sẽ không đi."},{"context":"“Tôi nghĩ anh ấy sẽ thích món quà này.”","pre":"我想他","blank":"会","post":"喜欢这个礼物。","options":["会","能","要"],"answer":0,"explanation":"Dự đoán dùng 会."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"明天会下雨了。","isCorrect":false,"correctVersion":"明天会下雨。","explanation":"会 nói việc chưa xảy ra, không dùng với 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他会不会来？","isCorrect":true,"explanation":"Mẫu chính phản 会不会 + động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai (ý: bận nên không đi được).","sentence":"明天我有事，不会去。","isCorrect":false,"correctVersion":"明天我有事，不能去。","explanation":"Vì điều kiện không cho phép thì dùng 不能."},{"type":"sort","context":"Sắp xếp: “Ngày mai chắc trời sẽ mưa.”","words":["明天","可能","会","下雨","。"],"answer":"明天可能会下雨。","explanation":"可能 + 会 tăng sắc thái phỏng đoán."},{"type":"sort","context":"Sắp xếp: “Anh ấy sẽ không đến đâu.”","words":["他","不","会","来","的","。"],"answer":"他不会来的。","explanation":"不会…的 = chắc chắn sẽ không."},{"type":"sort","context":"Sắp xếp: “Bạn nghĩ cô ấy có đến không?”","words":["你","想","她","会不会","来","？"],"answer":"你想她会不会来？","explanation":"会不会 trong câu hỏi lồng."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 会.","promptLang":"vi","prompt":"Ngày mai trời sẽ không mưa đâu.","answer":"明天不会下雨。","answerPy":"Míngtiān bú huì xià yǔ.","explanation":"不会 + động từ (dự đoán phủ định)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 会.","promptLang":"vi","prompt":"Tôi nghĩ anh ấy sẽ thích món quà này.","answer":"我想他会喜欢这个礼物。","answerPy":"Wǒ xiǎng tā huì xǐhuan zhège lǐwù.","explanation":"会 dùng cho dự đoán."}]}],"/lessons/hsk3-bai-4.html":[{"point":"「又……又……」 — hai đặc điểm cùng tồn tại","items":[{"context":"“Món này vừa ngon vừa rẻ.”","pre":"这个菜","blank":"又好吃又便宜","post":"。","options":["又好吃又便宜","又好吃又很便宜","好吃又便宜又"],"answer":0,"explanation":"Hai vế cùng là tính từ, không thêm 很."},{"context":"“Anh ấy vừa cao vừa gầy.”","pre":"他","blank":"又高又瘦","post":"。","options":["又高又瘦","又高瘦又","又是高又瘦"],"answer":0,"explanation":"又 + tính từ + 又 + tính từ."},{"context":"“Cô ấy vừa biết hát vừa biết nhảy.”","pre":"她","blank":"又会唱歌又会跳舞","post":"。","options":["又会唱歌又会跳舞","又唱歌又会跳舞","会又唱歌又跳舞"],"answer":0,"explanation":"Hai vế cùng cấu trúc 会 + động từ."},{"context":"Nói hai việc xảy ra LẦN LƯỢT thì dùng 一边……一边…….","pre":"他","blank":"一边吃饭一边看电视","post":"。","options":["一边吃饭一边看电视","又吃饭又看电视了","又一边吃饭又看电视"],"answer":0,"explanation":"一边…一边… = vừa làm A vừa làm B cùng lúc."},{"context":"“Phòng này vừa to vừa sáng.”","pre":"这个房间","blank":"又大又亮","post":"。","options":["又大又亮","又大亮又","大又亮又"],"answer":0,"explanation":"Khung cố định 又…又…"},{"context":"“Hôm nay tôi vừa mệt vừa đói.”","pre":"今天我","blank":"又累又饿","post":"。","options":["又累又饿","又累又很饿","累又饿又"],"answer":0,"explanation":"Không chen 很 vào khung."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个菜又好吃又很便宜。","isCorrect":false,"correctVersion":"这个菜又好吃又便宜。","explanation":"Khung 又…又… không dùng thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她又会唱歌又会跳舞。","isCorrect":true,"explanation":"Hai vế cùng dạng 会 + động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他又高又是学生。","isCorrect":false,"correctVersion":"他又高又瘦。","explanation":"Hai vế phải cùng loại từ."},{"type":"sort","context":"Sắp xếp: “Món này vừa ngon vừa rẻ.”","words":["这个","菜","又","好吃","又","便宜","。"],"answer":"这个菜又好吃又便宜。","explanation":"又 + tính từ + 又 + tính từ."},{"type":"sort","context":"Sắp xếp: “Phòng này vừa to vừa sạch.”","words":["这个","房间","又","大","又","干净","。"],"answer":"这个房间又大又干净。","explanation":"Khung 又…又… tả hai đặc điểm."},{"type":"sort","context":"Sắp xếp: “Cô ấy vừa biết tiếng Trung vừa biết tiếng Anh.”","words":["她","又","会","汉语","又","会","英语","。"],"answer":"她又会汉语又会英语。","explanation":"Hai vế cùng cấu trúc."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 又……又…….","promptLang":"vi","prompt":"Món này vừa ngon vừa rẻ.","answer":"这个菜又好吃又便宜。","answerPy":"Zhège cài yòu hǎochī yòu piányi.","explanation":"Không thêm 很 vào khung."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 又……又…….","promptLang":"vi","prompt":"Hôm nay tôi vừa mệt vừa đói.","answer":"今天我又累又饿。","answerPy":"Jīntiān wǒ yòu lèi yòu è.","explanation":"Hai tính từ cùng loại."}]},{"point":"Động tác đi kèm 「V1着(O1) + V2(O2)」","items":[{"context":"“Anh ấy vừa cười vừa nhìn tôi.” (cười là động tác kèm theo)","pre":"他","blank":"笑着看","post":"我。","options":["笑着看","看着笑","笑看着"],"answer":0,"explanation":"着 gắn vào động tác ĐI KÈM (V1), động tác chính đứng sau."},{"context":"“Cô ấy đứng nghe nhạc.”","pre":"她","blank":"站着听","post":"音乐。","options":["站着听","听着站","站听着"],"answer":0,"explanation":"站着 là tư thế, 听音乐 là việc chính."},{"context":"“Đừng vừa đi vừa xem điện thoại.”","pre":"别","blank":"走着看","post":"手机。","options":["走着看","看着走","走看着"],"answer":0,"explanation":"走着 = trong lúc đi."},{"context":"“Thầy cầm sách giảng bài.”","pre":"老师","blank":"拿着书","post":"讲课。","options":["拿着书","书拿着","讲着书"],"answer":0,"explanation":"V1着 + O1 + V2 + O2."},{"context":"“Mẹ vừa nấu cơm vừa nghe nhạc.” (hai việc song song, cùng mức)","pre":"妈妈","blank":"一边做饭一边听音乐","post":"。","options":["一边做饭一边听音乐","做着饭着听音乐","做饭着听音乐着"],"answer":0,"explanation":"Hai việc cùng mức dùng 一边…一边…; V着 dùng khi một việc làm nền cho việc kia."},{"context":"“Anh ấy ngồi đọc báo.”","pre":"他","blank":"坐着看","post":"报纸。","options":["坐着看","看着坐","坐看着"],"answer":0,"explanation":"坐着 là tư thế nền."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他笑看着我。","isCorrect":false,"correctVersion":"他笑着看我。","explanation":"着 gắn với động tác đi kèm 笑."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"老师拿着书讲课。","isCorrect":true,"explanation":"V1着 + O1 + V2: đúng khung."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"别走着看手机。","isCorrect":true,"explanation":"走着 làm nền cho 看手机 — lời nhắc rất tự nhiên."},{"type":"sort","context":"Sắp xếp: “Anh ấy cười nói với tôi.”","words":["他","笑","着","对","我","说","。"],"answer":"他笑着对我说。","explanation":"笑着 + 对我说."},{"type":"sort","context":"Sắp xếp: “Cô ấy đứng đợi bạn.”","words":["她","站","着","等","朋友","。"],"answer":"她站着等朋友。","explanation":"站着 là tư thế nền."},{"type":"sort","context":"Sắp xếp: “Thầy cầm sách bước vào lớp.”","words":["老师","拿","着","书","走","进","教室","。"],"answer":"老师拿着书走进教室。","explanation":"V1着 + O1 + V2 + nơi chốn."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng V着.","promptLang":"vi","prompt":"Anh ấy vừa cười vừa nhìn tôi.","answer":"他笑着看我。","answerPy":"Tā xiàozhe kàn wǒ.","explanation":"着 gắn với động tác đi kèm."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng V着.","promptLang":"vi","prompt":"Đừng vừa đi vừa xem điện thoại.","answer":"别走着看手机。","answerPy":"Bié zǒuzhe kàn shǒujī.","explanation":"走着 làm nền, 看手机 là việc chính."}]}],"/lessons/hsk3-bai-13.html":[{"point":"Bổ ngữ chỉ phương hướng dạng kết hợp (复合趋向补语)","items":[{"context":"“Anh ấy đi vào trong lớp.” (người nói ở trong lớp)","pre":"他走","blank":"进教室来","post":"了。","options":["进教室来","进来教室","来进教室"],"answer":0,"explanation":"Tân ngữ nơi chốn 教室 đứng TRƯỚC 来."},{"context":"“Cô ấy đi lên trên gác.” (người nói ở dưới)","pre":"她走","blank":"上楼去","post":"了。","options":["上楼去","上去楼","去上楼"],"answer":0,"explanation":"V + 上 + nơi chốn + 去."},{"context":"“Tôi lấy ra một quyển sách.” (tân ngữ là sự vật)","pre":"我","blank":"拿出一本书来","post":"。","options":["拿出一本书来","拿来出一本书","拿来一本书出"],"answer":0,"explanation":"Tân ngữ sự vật có thể đứng giữa 出 và 来."},{"context":"Tân ngữ sự vật cũng được đặt sau 出来.","pre":"我","blank":"拿出来一本书","post":"。","options":["拿出来一本书","拿一本书出来了来","出来拿一本书"],"answer":0,"explanation":"Cả hai vị trí đều đúng với tân ngữ sự vật."},{"context":"“Mời bạn vào đây.” (người nói ở trong)","pre":"请","blank":"进来","post":"吧。","options":["进来","来进","进去"],"answer":0,"explanation":"Người nói ở TRONG nên dùng 来."},{"context":"“Cậu ấy chạy ra khỏi nhà.” (người nói ở trong nhà)","pre":"他","blank":"跑出家去","post":"了。","options":["跑出家去","跑出去家","跑去出家"],"answer":0,"explanation":"Hướng ra xa người nói nên dùng 去; nơi chốn trước 去."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他走进来教室了。","isCorrect":false,"correctVersion":"他走进教室来了。","explanation":"Tân ngữ nơi chốn phải đứng trước 来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我拿出来一本书。","isCorrect":true,"explanation":"Tân ngữ sự vật đứng sau 出来 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她走上去楼了。","isCorrect":false,"correctVersion":"她走上楼去了。","explanation":"楼 là nơi chốn, phải đứng trước 去."},{"type":"sort","context":"Sắp xếp: “Thầy đi vào trong lớp rồi.”","words":["老师","走","进","教室","来","了","。"],"answer":"老师走进教室来了。","explanation":"V + 进 + nơi chốn + 来."},{"type":"sort","context":"Sắp xếp: “Tôi lấy ra một quyển sách.”","words":["我","拿","出","一","本","书","来","。"],"answer":"我拿出一本书来。","explanation":"Tân ngữ sự vật giữa 出 và 来."},{"type":"sort","context":"Sắp xếp: “Cậu ấy chạy lên trên gác.”","words":["他","跑","上","楼","去","了","。"],"answer":"他跑上楼去了。","explanation":"跑上 + 楼 + 去."},{"type":"translate","context":"Dịch sang tiếng Trung (người nói đang ở trong lớp).","promptLang":"vi","prompt":"Thầy đi vào lớp rồi.","answer":"老师走进教室来了。","answerPy":"Lǎoshī zǒu jìn jiàoshì lái le.","explanation":"Nơi chốn 教室 đứng trước 来."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ phương hướng kết hợp.","promptLang":"vi","prompt":"Cô ấy lấy ra một chiếc áo.","answer":"她拿出一件衣服来。","answerPy":"Tā ná chū yí jiàn yīfu lái.","explanation":"拿出……来."}]},{"point":"「一边……一边……」 — hai việc cùng lúc","items":[{"context":"“Anh ấy vừa ăn cơm vừa xem TV.”","pre":"他","blank":"一边吃饭，一边看电视","post":"。","options":["一边吃饭，一边看电视","一边吃饭，我一边看电视","吃饭一边，看电视一边"],"answer":0,"explanation":"Cùng một chủ thể làm hai việc song song."},{"context":"Có thể lược 一 thành 边……边…….","pre":"他","blank":"边走边说","post":"。","options":["边走边说","一边走边一说","走边说边"],"answer":0,"explanation":"边 + V1 + 边 + V2, thường dùng với động từ đơn âm."},{"context":"“Chúng tôi vừa nghe nhạc vừa học.”","pre":"我们","blank":"一边听音乐，一边学习","post":"。","options":["一边听音乐，一边学习","一边听音乐，一边很累","听音乐一边学习一边"],"answer":0,"explanation":"Hai vế đều là hành động."},{"context":"Hai chủ thể KHÁC nhau thì không dùng 一边……一边…….","pre":"他吃饭，我","blank":"看电视","post":"。","options":["看电视","一边看电视","一边看电视一边"],"answer":0,"explanation":"一边……一边…… chỉ dùng cho MỘT chủ thể."},{"context":"“Đừng vừa đi vừa nhìn điện thoại.”","pre":"别","blank":"一边走路，一边看手机","post":"。","options":["一边走路，一边看手机","一边走路，一边手机","走路一边看手机一边"],"answer":0,"explanation":"别 đứng đầu câu mệnh lệnh phủ định."},{"context":"“Cô ấy vừa làm việc vừa học tiếng Trung.”","pre":"她","blank":"一边工作，一边学汉语","post":"。","options":["一边工作，一边学汉语","一边工作了，一边学汉语","工作一边汉语学一边"],"answer":0,"explanation":"Không chen 了 vào khung."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他一边吃饭，我一边看电视。","isCorrect":false,"correctVersion":"他一边吃饭，一边看电视。","explanation":"Hai vế phải cùng một chủ thể."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他们边走边聊。","isCorrect":true,"explanation":"边……边…… là dạng lược của 一边……一边……."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他一边很累，一边工作。","isCorrect":false,"correctVersion":"他一边听音乐，一边工作。","explanation":"一边 nối hai hành động, không nối tính từ."},{"type":"sort","context":"Sắp xếp: “Anh ấy vừa ăn cơm vừa xem TV.”","words":["他","一边","吃饭","，","一边","看","电视","。"],"answer":"他一边吃饭，一边看电视。","explanation":"Khung 一边……一边……."},{"type":"sort","context":"Sắp xếp: “Chúng tôi vừa đi vừa nói chuyện.”","words":["我们","边","走","边","聊天","。"],"answer":"我们边走边聊天。","explanation":"Dạng lược 边……边……."},{"type":"sort","context":"Sắp xếp: “Đừng vừa đi vừa nhìn điện thoại.”","words":["别","一边","走路","，","一边","看","手机","。"],"answer":"别一边走路，一边看手机。","explanation":"别 + 一边……一边……."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 一边……一边…….","promptLang":"vi","prompt":"Cô ấy vừa nghe nhạc vừa làm bài tập.","answer":"她一边听音乐，一边做作业。","answerPy":"Tā yìbiān tīng yīnyuè, yìbiān zuò zuòyè.","explanation":"Cùng một chủ thể, hai hành động song song."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 边……边…….","promptLang":"vi","prompt":"Chúng tôi vừa đi vừa nói chuyện.","answer":"我们边走边聊天。","answerPy":"Wǒmen biān zǒu biān liáotiān.","explanation":"Động từ đơn âm hay dùng dạng lược."}]}],"/lessons/hsk3-bai-14.html":[{"point":"Câu chữ 「把」(3): 「把 B + động từ + bổ ngữ kết quả/xu hướng」","items":[{"context":"“Tôi đã dọn phòng sạch sẽ.”","pre":"我","blank":"把房间打扫干净了","post":"。","options":["把房间打扫干净了","把房间打扫","打扫干净把房间了"],"answer":0,"explanation":"把 + B + V + bổ ngữ kết quả 干净 + 了."},{"context":"“Mời bạn mang quyển sách lại đây.”","pre":"请","blank":"把书拿过来","post":"。","options":["把书拿过来","把书拿","拿过来把书"],"answer":0,"explanation":"把 + B + V + bổ ngữ xu hướng 过来."},{"context":"“Cậu ấy ăn hết cơm rồi.”","pre":"他","blank":"把饭吃完了","post":"。","options":["把饭吃完了","把饭吃了完","吃完把饭了"],"answer":0,"explanation":"吃完 = bổ ngữ kết quả."},{"context":"Phủ định: “Tôi chưa giặt sạch quần áo.”","pre":"我","blank":"没把衣服洗干净","post":"。","options":["没把衣服洗干净","把衣服没洗干净","把没衣服洗干净"],"answer":0,"explanation":"没 đứng trước 把."},{"context":"“Bạn hãy làm xong bài tập rồi đi ngủ.”","pre":"你","blank":"把作业做完","post":"以后再睡吧。","options":["把作业做完","把作业做","做完把作业"],"answer":0,"explanation":"做完 = V + bổ ngữ kết quả."},{"context":"“Cô ấy viết tấm thiệp đó xong rồi.”","pre":"她","blank":"把那张卡片写好了","post":"。","options":["把那张卡片写好了","把那张卡片写","写好把那张卡片"],"answer":0,"explanation":"写好 = viết xong, đạt kết quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把房间打扫。","isCorrect":false,"correctVersion":"我把房间打扫干净了。","explanation":"Câu 把 cần bổ ngữ kết quả sau động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"请把这本书拿过来。","isCorrect":true,"explanation":"把 + B + V + bổ ngữ xu hướng — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把衣服没洗干净。","isCorrect":false,"correctVersion":"我没把衣服洗干净。","explanation":"没 phải đứng trước 把."},{"type":"sort","context":"Sắp xếp: “Tôi đã dọn phòng sạch sẽ rồi.”","words":["我","把","房间","打扫","干净","了","。"],"answer":"我把房间打扫干净了。","explanation":"把 + B + V + 干净 + 了."},{"type":"sort","context":"Sắp xếp: “Mời bạn mang quyển sách lại đây.”","words":["请","你","把","书","拿","过来","。"],"answer":"请你把书拿过来。","explanation":"拿过来 = bổ ngữ xu hướng."},{"type":"sort","context":"Sắp xếp: “Cậu ấy ăn hết cơm rồi.”","words":["他","把","饭","吃","完","了","。"],"answer":"他把饭吃完了。","explanation":"吃完了 = ăn xong."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Tôi đã giặt sạch quần áo rồi.","answer":"我把衣服洗干净了。","answerPy":"Wǒ bǎ yīfu xǐ gānjìng le.","explanation":"洗干净了 = giặt sạch rồi."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Bạn mang chiếc ghế kia lại đây nhé.","answer":"你把那把椅子拿过来吧。","answerPy":"Nǐ bǎ nà bǎ yǐzi ná guòlái ba.","explanation":"拿过来 = mang lại đây."}]},{"point":"「先……，再/又……，然后……」 — trình tự hành động","items":[{"context":"Kế hoạch NGÀY MAI (chưa xảy ra).","pre":"明天我先去银行，","blank":"再","post":"去超市。","options":["再","又","还"],"answer":0,"explanation":"再 dùng cho việc CHƯA xảy ra."},{"context":"Kể lại việc HÔM QUA (đã xảy ra).","pre":"昨天我先吃了饭，","blank":"又","post":"看了电视。","options":["又","再","就"],"answer":0,"explanation":"又 dùng cho việc ĐÃ xảy ra."},{"context":"“Tôi ăn cơm trước, sau đó làm bài tập.”","pre":"我","blank":"先吃饭，然后做作业","post":"。","options":["先吃饭，然后做作业","然后吃饭，先做作业","先吃饭，先做作业"],"answer":0,"explanation":"先……，然后…… nêu trình tự trước sau."},{"context":"Ba bước liên tiếp.","pre":"我先起床，","blank":"再吃早饭，然后去学校","post":"。","options":["再吃早饭，然后去学校","然后吃早饭，再然后去学校再","又吃早饭，再去学校了"],"answer":0,"explanation":"先 → 再 → 然后."},{"context":"“Bạn làm xong bài tập trước rồi hãy chơi.”","pre":"你","blank":"先做完作业，再玩","post":"。","options":["先做完作业，再玩","先做完作业，又玩","又做完作业，先玩"],"answer":0,"explanation":"Việc chưa xảy ra → 再."},{"context":"“Hôm qua cô ấy đi bệnh viện trước, sau đó về nhà.”","pre":"昨天她先去了医院，","blank":"然后回家了","post":"。","options":["然后回家了","再回家了","先回家了"],"answer":0,"explanation":"然后 dùng được cho cả việc đã xảy ra."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"昨天我先吃饭，再看电视。","isCorrect":false,"correctVersion":"昨天我先吃了饭，又看了电视。","explanation":"Việc đã xảy ra dùng 又."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"明天我先去银行，再去超市。","isCorrect":true,"explanation":"Việc chưa xảy ra dùng 再 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我然后吃饭，先看电视。","isCorrect":false,"correctVersion":"我先吃饭，然后看电视。","explanation":"先 đứng ở vế đầu, 然后 ở vế sau."},{"type":"sort","context":"Sắp xếp: “Tôi ăn cơm trước, sau đó làm bài tập.”","words":["我","先","吃饭","，","然后","做","作业","。"],"answer":"我先吃饭，然后做作业。","explanation":"先……然后……."},{"type":"sort","context":"Sắp xếp: “Ngày mai tôi đi ngân hàng trước, rồi đi siêu thị.”","words":["明天","我","先","去","银行","，","再","去","超市","。"],"answer":"明天我先去银行，再去超市。","explanation":"Việc tương lai → 再."},{"type":"sort","context":"Sắp xếp: “Bạn làm xong bài tập trước rồi hãy chơi.”","words":["你","先","做完","作业","，","再","玩","吧","。"],"answer":"你先做完作业，再玩吧。","explanation":"先……再…… trong câu đề nghị."},{"type":"translate","context":"Dịch sang tiếng Trung (kế hoạch ngày mai).","promptLang":"vi","prompt":"Ngày mai tôi đi bệnh viện trước, rồi đi làm.","answer":"明天我先去医院，再去上班。","answerPy":"Míngtiān wǒ xiān qù yīyuàn, zài qù shàngbān.","explanation":"Việc chưa xảy ra → 再."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 先……然后…….","promptLang":"vi","prompt":"Tôi tắm trước, sau đó đi ngủ.","answer":"我先洗澡，然后睡觉。","answerPy":"Wǒ xiān xǐzǎo, ránhòu shuìjiào.","explanation":"先……然后…… nêu trình tự."}]}],"/lessons/hsk3-bai-15.html":[{"point":"「除了……以外，都/还/也……」","items":[{"context":"“Ngoài Tiểu Vương, chúng tôi đều đi.” (Tiểu Vương KHÔNG đi)","pre":"除了小王以外，","blank":"我们都去了","post":"。","options":["我们都去了","我们还去了","都我们去了"],"answer":0,"explanation":"都 = loại trừ; phần còn lại giống nhau."},{"context":"“Ngoài tiếng Trung, tôi còn biết nói tiếng Anh.” (biết cả hai)","pre":"除了汉语以外，我","blank":"还","post":"会说英语。","options":["还","都","才"],"answer":0,"explanation":"还/也 = bao gồm thêm."},{"context":"以外 có thể lược bỏ.","pre":"除了他，我们","blank":"都","post":"是学生。","options":["都","还","又"],"answer":0,"explanation":"除了 A，都…… vẫn đúng khi bỏ 以外."},{"context":"“Ngoài bóng đá, cậu ấy cũng thích bóng rổ.”","pre":"除了足球以外，他","blank":"也","post":"喜欢篮球。","options":["也","都","就"],"answer":0,"explanation":"也 = còn, cũng (bao gồm thêm)."},{"context":"“Ngoài thứ Bảy, ngày nào tôi cũng có lớp.”","pre":"除了星期六以外，我","blank":"每天都有课","post":"。","options":["每天都有课","每天还有课","都每天有课"],"answer":0,"explanation":"Loại trừ thứ Bảy → dùng 都."},{"context":"Chủ ngữ có thể đặt ở ĐẦU câu.","pre":"我们班","blank":"除了他以外都来了","post":"。","options":["除了他以外都来了","除了以外他都来了","都除了他以外来了"],"answer":0,"explanation":"以外 đứng sau thành phần bị loại trừ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"除了汉语以外，我都会说英语。","isCorrect":false,"correctVersion":"除了汉语以外，我还会说英语。","explanation":"“Biết thêm” thì dùng 还/也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"除了小王以外，我们都去了。","isCorrect":true,"explanation":"都 loại trừ Tiểu Vương — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"除了以外小王，我们都去了。","isCorrect":false,"correctVersion":"除了小王以外，我们都去了。","explanation":"以外 đứng sau 小王."},{"type":"sort","context":"Sắp xếp: “Ngoài Tiểu Vương, chúng tôi đều đi rồi.”","words":["除了","小王","以外","，","我们","都","去","了","。"],"answer":"除了小王以外，我们都去了。","explanation":"除了……以外，都……."},{"type":"sort","context":"Sắp xếp: “Ngoài tiếng Trung, tôi còn biết nói tiếng Anh.”","words":["除了","汉语","以外","，","我","还","会","说","英语","。"],"answer":"除了汉语以外，我还会说英语。","explanation":"除了……以外，还……."},{"type":"sort","context":"Sắp xếp: “Ngoài thứ Bảy, ngày nào tôi cũng có lớp.”","words":["除了","星期六","以外","，","我","每天","都","有","课","。"],"answer":"除了星期六以外，我每天都有课。","explanation":"都 nêu phần còn lại giống nhau."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 除了……以外，都…….","promptLang":"vi","prompt":"Ngoài cậu ấy, cả lớp chúng tôi đều đến rồi.","answer":"除了他以外，我们班都来了。","answerPy":"Chúle tā yǐwài, wǒmen bān dōu lái le.","explanation":"都 = loại trừ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 除了……以外，还…….","promptLang":"vi","prompt":"Ngoài bóng đá, cậu ấy còn thích bóng rổ.","answer":"除了足球以外，他还喜欢篮球。","answerPy":"Chúle zúqiú yǐwài, tā hái xǐhuan lánqiú.","explanation":"还 = bao gồm thêm."}]},{"point":"「什么」 làm đại từ chỉ thị không xác định","items":[{"context":"Hỏi lịch sự: “Bạn có vấn đề gì không?”","pre":"你","blank":"有什么问题吗","post":"？","options":["有什么问题吗","有什么问题没有吗","什么有问题吗"],"answer":0,"explanation":"有 + 什么 + N + 吗 — cách hỏi lịch sự."},{"context":"“Tôi không có việc gì cả.”","pre":"我","blank":"没有什么事","post":"。","options":["没有什么事","没有什么的事","什么没有事"],"answer":0,"explanation":"没 + 什么 + N; không chen 的."},{"context":"“Có chuyện gì thì gọi tôi nhé.”","pre":"","blank":"有什么事就给我打电话","post":"吧。","options":["有什么事就给我打电话","什么有事就给我打电话","有事什么就给我打电话"],"answer":0,"explanation":"什么 chỉ sự việc không xác định."},{"context":"Lược bỏ 什么 nghĩa vẫn không đổi.","pre":"你有","blank":"问题","post":"吗？","options":["问题","什么的问题","问题什么"],"answer":0,"explanation":"Bỏ 什么 câu vẫn đúng, chỉ bớt phần lịch sự."},{"context":"“Cậu ấy chẳng nói gì cả.”","pre":"他","blank":"没说什么","post":"。","options":["没说什么","什么没说的","没什么说的话什么"],"answer":0,"explanation":"没说什么 = không nói gì."},{"context":"“Bạn muốn ăn gì?”","pre":"你想吃","blank":"什么","post":"？","options":["什么","什么的","有什么吗什么"],"answer":0,"explanation":"什么 ở vị trí tân ngữ, cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你有什么问题吗？","isCorrect":true,"explanation":"Cách hỏi lịch sự với 什么 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我没有什么的事。","isCorrect":false,"correctVersion":"我没有什么事。","explanation":"Không chen 的 giữa 什么 và danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"什么你想吃？","isCorrect":false,"correctVersion":"你想吃什么？","explanation":"什么 đứng ở vị trí tân ngữ."},{"type":"sort","context":"Sắp xếp: “Bạn có vấn đề gì không?”","words":["你","有","什么","问题","吗","？"],"answer":"你有什么问题吗？","explanation":"有 + 什么 + N + 吗."},{"type":"sort","context":"Sắp xếp: “Tôi không có việc gì cả.”","words":["我","没有","什么","事","。"],"answer":"我没有什么事。","explanation":"没有 + 什么 + N."},{"type":"sort","context":"Sắp xếp: “Có việc gì thì gọi tôi nhé.”","words":["有","什么","事","就","给","我","打","电话","吧","。"],"answer":"有什么事就给我打电话吧。","explanation":"有什么事 = có việc gì."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 什么 chỉ sự việc không xác định.","promptLang":"vi","prompt":"Bạn có vấn đề gì không?","answer":"你有什么问题吗？","answerPy":"Nǐ yǒu shénme wèntí ma?","explanation":"Cách hỏi lịch sự."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 什么.","promptLang":"vi","prompt":"Tôi không có việc gì cả.","answer":"我没有什么事。","answerPy":"Wǒ méiyǒu shénme shì.","explanation":"没有什么 + N."}]},{"point":"「……极了」 — mức độ cao nhất","items":[{"context":"“Hôm nay nóng cực kỳ.”","pre":"今天","blank":"热极了","post":"。","options":["热极了","很热极了","极了热"],"answer":0,"explanation":"Tính từ + 极了, không thêm 很."},{"context":"“Món này ngon cực kỳ.”","pre":"这个菜","blank":"好吃极了","post":"。","options":["好吃极了","极了好吃","非常好吃极了"],"answer":0,"explanation":"极了 đứng sau tính từ."},{"context":"“Tôi vui lắm.” (động từ chỉ tâm lý)","pre":"我","blank":"高兴极了","post":"。","options":["高兴极了","极了高兴","很高兴极了"],"answer":0,"explanation":"Động từ chỉ trạng thái tâm lý cũng dùng được 极了."},{"context":"Phủ định thì KHÔNG dùng 极了.","pre":"这个菜","blank":"不好吃","post":"。","options":["不好吃","不好吃极了","极了不好吃"],"answer":0,"explanation":"极了 chỉ dùng trong câu khẳng định."},{"context":"“Cảnh ở đây đẹp cực kỳ.”","pre":"这儿的风景","blank":"美极了","post":"。","options":["美极了","很美极了","极了美"],"answer":0,"explanation":"Tính từ + 极了."},{"context":"“Bài thi lần này khó cực kỳ.”","pre":"这次考试","blank":"难极了","post":"。","options":["难极了","极了难","太难极了"],"answer":0,"explanation":"Không dùng 太 cùng 极了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"今天很热极了。","isCorrect":false,"correctVersion":"今天热极了。","explanation":"极了 không đi cùng 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个菜好吃极了。","isCorrect":true,"explanation":"Tính từ + 极了 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个菜不好吃极了。","isCorrect":false,"correctVersion":"这个菜不好吃。","explanation":"极了 không dùng trong câu phủ định."},{"type":"sort","context":"Sắp xếp: “Hôm nay nóng cực kỳ.”","words":["今天","热","极了","。"],"answer":"今天热极了。","explanation":"Tính từ + 极了."},{"type":"sort","context":"Sắp xếp: “Tôi vui lắm.”","words":["我","高兴","极了","。"],"answer":"我高兴极了。","explanation":"Động từ tâm lý + 极了."},{"type":"sort","context":"Sắp xếp: “Cảnh ở đây đẹp cực kỳ.”","words":["这儿","的","风景","美","极了","。"],"answer":"这儿的风景美极了。","explanation":"Cụm danh từ + tính từ + 极了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng ……极了.","promptLang":"vi","prompt":"Món này ngon cực kỳ.","answer":"这个菜好吃极了。","answerPy":"Zhège cài hǎochī jí le.","explanation":"好吃极了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng ……极了.","promptLang":"vi","prompt":"Bài thi lần này khó cực kỳ.","answer":"这次考试难极了。","answerPy":"Zhè cì kǎoshì nán jí le.","explanation":"难极了."}]}],"/lessons/hsk3-bai-16.html":[{"point":"「如果……，就……」 — câu giả thiết","items":[{"context":"“Nếu mai mưa thì chúng ta không đi.”","pre":"如果明天下雨，","blank":"我们就不去","post":"。","options":["我们就不去","就我们不去","我们不去就"],"answer":0,"explanation":"Chủ ngữ vế sau đứng TRƯỚC 就."},{"context":"Có thể thêm 的话 ở cuối vế giả thiết.","pre":"如果你有时间","blank":"的话，就来我家吧","post":"。","options":["的话，就来我家吧","就的话，来我家吧","的话就，来我家吧"],"answer":0,"explanation":"如果……的话，(chủ ngữ) + 就……."},{"context":"“Nếu bạn thích thì tôi tặng bạn.”","pre":"如果你喜欢，","blank":"我就送给你","post":"。","options":["我就送给你","就我送给你","我送给你就"],"answer":0,"explanation":"就 đứng trước động từ."},{"context":"Cùng một chủ ngữ thì vế sau có thể lược chủ ngữ.","pre":"如果我有钱，","blank":"就去中国旅游","post":"。","options":["就去中国旅游","去中国旅游就","就我去中国旅游"],"answer":0,"explanation":"Chủ ngữ giống nhau nên lược ở vế sau."},{"context":"“Nếu ngày mai bạn không đến thì gọi điện cho tôi nhé.”","pre":"如果明天你不来，","blank":"就给我打个电话","post":"。","options":["就给我打个电话","给我打个电话就","就打个电话给我吗"],"answer":0,"explanation":"就 + cụm động từ."},{"context":"“Nếu bị bệnh thì nên đi bệnh viện.”","pre":"如果生病了，","blank":"就应该去医院","post":"。","options":["就应该去医院","应该就去医院了吧","就去医院应该"],"answer":0,"explanation":"就 đứng trước động từ năng nguyện 应该."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"如果明天下雨，我们就不去。","isCorrect":true,"explanation":"Chủ ngữ trước 就 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"如果明天下雨，就我们不去。","isCorrect":false,"correctVersion":"如果明天下雨，我们就不去。","explanation":"Chủ ngữ vế sau đứng trước 就."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"如果你喜欢，我送给你就。","isCorrect":false,"correctVersion":"如果你喜欢，我就送给你。","explanation":"就 đứng trước động từ, không đứng cuối câu."},{"type":"sort","context":"Sắp xếp: “Nếu mai mưa thì chúng ta không đi.”","words":["如果","明天","下雨","，","我们","就","不","去","。"],"answer":"如果明天下雨，我们就不去。","explanation":"如果……，chủ ngữ + 就 + ……."},{"type":"sort","context":"Sắp xếp: “Nếu bạn có thời gian thì đến nhà tôi nhé.”","words":["如果","你","有","时间","的话","，","就","来","我","家","吧","。"],"answer":"如果你有时间的话，就来我家吧。","explanation":"的话 ở cuối vế giả thiết."},{"type":"sort","context":"Sắp xếp: “Nếu bạn thích thì tôi tặng bạn.”","words":["如果","你","喜欢","，","我","就","送","给","你","。"],"answer":"如果你喜欢，我就送给你。","explanation":"就 trước động từ 送."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 如果……就…….","promptLang":"vi","prompt":"Nếu ngày mai mưa thì chúng ta không đi.","answer":"如果明天下雨，我们就不去。","answerPy":"Rúguǒ míngtiān xiàyǔ, wǒmen jiù bú qù.","explanation":"Chủ ngữ vế sau trước 就."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 如果……的话，就…….","promptLang":"vi","prompt":"Nếu bạn có thời gian thì đến nhà tôi nhé.","answer":"如果你有时间的话，就来我家吧。","answerPy":"Rúguǒ nǐ yǒu shíjiān de huà, jiù lái wǒ jiā ba.","explanation":"的话 + 就."}]},{"point":"Bổ ngữ chỉ trạng thái với 「得」","items":[{"context":"“Cậu ấy vui đến nhảy cẫng lên.”","pre":"他高兴","blank":"得跳起来了","post":"。","options":["得跳起来了","的跳起来了","地跳起来了"],"answer":0,"explanation":"Bổ ngữ trạng thái dùng 得."},{"context":"“Cậu ấy mệt đến không nói được câu nào.”","pre":"他累","blank":"得说不出话来","post":"。","options":["得说不出话来","的说不出话来","得很说不出话来"],"answer":0,"explanation":"得 + cụm động từ miêu tả mức độ."},{"context":"“Cô ấy khóc đến đôi mắt đỏ hoe.”","pre":"她哭","blank":"得眼睛都红了","post":"。","options":["得眼睛都红了","的眼睛都红了","得红眼睛都了"],"answer":0,"explanation":"得 + cụm chủ-vị miêu tả kết quả."},{"context":"“Trời nóng đến tôi không muốn ra ngoài.”","pre":"天气热","blank":"得我不想出去","post":"。","options":["得我不想出去","的我不想出去","得不想我出去"],"answer":0,"explanation":"得 + cụm chủ-vị."},{"context":"So sánh: 的 dùng trước danh từ.","pre":"这是我","blank":"的","post":"书。","options":["的","得","地"],"answer":0,"explanation":"的 + danh từ; 得 + bổ ngữ trạng thái."},{"context":"“Cậu ấy bận đến không có thời gian ăn cơm.”","pre":"他忙","blank":"得没时间吃饭","post":"。","options":["得没时间吃饭","的没时间吃饭","得吃饭没时间的"],"answer":0,"explanation":"得 + cụm động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他高兴的跳起来了。","isCorrect":false,"correctVersion":"他高兴得跳起来了。","explanation":"Bổ ngữ trạng thái dùng 得, không dùng 的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她哭得眼睛都红了。","isCorrect":true,"explanation":"得 + cụm chủ-vị — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他得高兴跳起来了。","isCorrect":false,"correctVersion":"他高兴得跳起来了。","explanation":"得 đứng sau tính từ."},{"type":"sort","context":"Sắp xếp: “Cậu ấy vui đến nhảy cẫng lên.”","words":["他","高兴","得","跳","起来","了","。"],"answer":"他高兴得跳起来了。","explanation":"Tính từ + 得 + cụm động từ."},{"type":"sort","context":"Sắp xếp: “Cô ấy khóc đến đôi mắt đỏ hoe.”","words":["她","哭","得","眼睛","都","红","了","。"],"answer":"她哭得眼睛都红了。","explanation":"Động từ + 得 + cụm chủ-vị."},{"type":"sort","context":"Sắp xếp: “Cậu ấy bận đến không có thời gian ăn cơm.”","words":["他","忙","得","没","时间","吃饭","。"],"answer":"他忙得没时间吃饭。","explanation":"忙得 + cụm động từ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ trạng thái với 得.","promptLang":"vi","prompt":"Cậu ấy vui đến nhảy cẫng lên.","answer":"他高兴得跳起来了。","answerPy":"Tā gāoxìng de tiào qǐlái le.","explanation":"高兴得 + 跳起来."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ trạng thái với 得.","promptLang":"vi","prompt":"Trời nóng đến tôi không muốn ra ngoài.","answer":"天气热得我不想出去。","answerPy":"Tiānqì rè de wǒ bù xiǎng chūqù.","explanation":"热得 + cụm chủ-vị."}]},{"point":"Tính từ đơn âm tiết lặp lại 「AA的」","items":[{"context":"“ngọn núi cao cao”","pre":"","blank":"高高的山","post":"","options":["高高的山","很高高的山","高高山"],"answer":0,"explanation":"AA的 + danh từ; không thêm 很."},{"context":"“bông hoa đỏ thắm”","pre":"","blank":"红红的花","post":"","options":["红红的花","红红花","很红红的花"],"answer":0,"explanation":"Cần 的 giữa dạng lặp và danh từ."},{"context":"“đôi mắt to tròn”","pre":"","blank":"大大的眼睛","post":"","options":["大大的眼睛","大大眼睛","很大大的眼睛"],"answer":0,"explanation":"大大的 = to to, dễ thương."},{"context":"Tính từ HAI âm tiết lặp theo dạng AABB.","pre":"","blank":"高高兴兴的","post":"孩子","options":["高高兴兴的","高兴高兴的","很高兴高兴的"],"answer":0,"explanation":"高兴 → 高高兴兴, không phải 高兴高兴."},{"context":"“con mèo trắng trắng”","pre":"一只","blank":"白白的","post":"猫。","options":["白白的","白白","很白白的"],"answer":0,"explanation":"AA的 + danh từ."},{"context":"Dạng lặp cũng làm vị ngữ được.","pre":"她的脸","blank":"红红的","post":"。","options":["红红的","很红红的","红红"],"answer":0,"explanation":"AA的 đứng cuối câu làm vị ngữ miêu tả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这是一座很高高的山。","isCorrect":false,"correctVersion":"这是一座高高的山。","explanation":"AA的 không đi cùng 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她有一双大大的眼睛。","isCorrect":true,"explanation":"AA的 + danh từ — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他是一个高兴高兴的孩子。","isCorrect":false,"correctVersion":"他是一个高高兴兴的孩子。","explanation":"Tính từ hai âm tiết lặp theo dạng AABB."},{"type":"sort","context":"Sắp xếp: “Đây là một ngọn núi cao cao.”","words":["这","是","一","座","高高","的","山","。"],"answer":"这是一座高高的山。","explanation":"AA的 làm định ngữ."},{"type":"sort","context":"Sắp xếp: “Cô ấy có đôi mắt to tròn.”","words":["她","有","一","双","大大","的","眼睛","。"],"answer":"她有一双大大的眼睛。","explanation":"大大的 + 眼睛."},{"type":"sort","context":"Sắp xếp: “Mặt cô ấy đỏ hồng.”","words":["她","的","脸","红红","的","。"],"answer":"她的脸红红的。","explanation":"AA的 làm vị ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng dạng lặp AA的.","promptLang":"vi","prompt":"Cô ấy có đôi mắt to tròn.","answer":"她有一双大大的眼睛。","answerPy":"Tā yǒu yì shuāng dàdà de yǎnjing.","explanation":"大大的."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng dạng lặp AA的.","promptLang":"vi","prompt":"Đó là một bông hoa đỏ thắm.","answer":"那是一朵红红的花。","answerPy":"Nà shì yì duǒ hónghóng de huā.","explanation":"红红的 + 花."}]}],"/lessons/hsk3-bai-5.html":[{"point":"Trợ từ 「了」 chỉ sự thay đổi","items":[{"context":"“Trời lạnh rồi.” (trước đó chưa lạnh)","pre":"天气冷","blank":"了","post":"。","options":["了","着","过"],"answer":0,"explanation":"了 cuối câu = tình hình đã THAY ĐỔI."},{"context":"“Tôi biết nói tiếng Trung rồi.”","pre":"我会说汉语","blank":"了","post":"。","options":["了","的","呢"],"answer":0,"explanation":"Từ chưa biết → biết: dùng 了."},{"context":"“Anh ấy không đến nữa.”","pre":"他不来","blank":"了","post":"。","options":["了","呢","吧"],"answer":0,"explanation":"不…了 = không… nữa (thay đổi ý định)."},{"context":"“Con gái tôi đã đi học tiểu học rồi.”","pre":"我女儿上小学","blank":"了","post":"。","options":["了","着","过"],"answer":0,"explanation":"Mốc mới trong cuộc sống."},{"context":"Nói THÓI QUEN không thay đổi thì KHÔNG dùng 了.","pre":"我每天七点","blank":"起床","post":"。","options":["起床","起床了","了起床"],"answer":0,"explanation":"每天… là thói quen lặp lại, không dùng 了."},{"context":"“Tôi không hút thuốc nữa.”","pre":"我不抽烟","blank":"了","post":"。","options":["了","过","着"],"answer":0,"explanation":"Thay đổi thói quen cũ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气了冷。","isCorrect":false,"correctVersion":"天气冷了。","explanation":"了 chỉ sự thay đổi đứng cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我每天七点起床了。","isCorrect":false,"correctVersion":"我每天七点起床。","explanation":"Thói quen lặp lại không dùng 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他不来了。","isCorrect":true,"explanation":"不…了 diễn đạt thay đổi so với dự định ban đầu."},{"type":"sort","context":"Sắp xếp: “Trời lạnh rồi, mặc thêm áo nhé.”","words":["天气","冷","了","，","多","穿","点儿","衣服","吧","。"],"answer":"天气冷了，多穿点儿衣服吧。","explanation":"Vế đầu báo thay đổi, vế sau khuyên."},{"type":"sort","context":"Sắp xếp: “Tôi biết nói tiếng Trung rồi.”","words":["我","会","说","汉语","了","。"],"answer":"我会说汉语了。","explanation":"了 cuối câu."},{"type":"sort","context":"Sắp xếp: “Anh ấy không muốn đi nữa.”","words":["他","不","想","去","了","。"],"answer":"他不想去了。","explanation":"不想…了 = không còn muốn nữa."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 了 chỉ sự thay đổi.","promptLang":"vi","prompt":"Trời mưa rồi, chúng ta đừng đi nữa.","answer":"下雨了，我们别去了。","answerPy":"Xià yǔ le, wǒmen bié qù le.","explanation":"Hai vế đều dùng 了 báo tình hình mới."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 了 chỉ sự thay đổi.","promptLang":"vi","prompt":"Con gái tôi đi học tiểu học rồi.","answer":"我女儿上小学了。","answerPy":"Wǒ nǚ'ér shàng xiǎoxué le.","explanation":"Mốc thay đổi mới."}]},{"point":"「越来越 + tính từ / động từ tâm lý」 — mức độ tăng dần","items":[{"context":"“Thời tiết ngày càng lạnh.”","pre":"天气","blank":"越来越冷","post":"。","options":["越来越冷","越来越很冷","越冷越来"],"answer":0,"explanation":"越来越 + tính từ, KHÔNG thêm 很."},{"context":"“Tôi ngày càng thích tiếng Trung.”","pre":"我","blank":"越来越喜欢","post":"汉语。","options":["越来越喜欢","越来越很喜欢","喜欢越来越"],"answer":0,"explanation":"越来越 + động từ tâm lý (喜欢, 想…)."},{"context":"“Cậu bé ngày càng cao.”","pre":"这个孩子","blank":"越来越高","post":"了。","options":["越来越高","越来越是高","高越来越"],"answer":0,"explanation":"Thường kèm 了 ở cuối để nhấn mạnh thay đổi."},{"context":"So sánh hai vế cùng tăng thì dùng 越……越…….","pre":"雨","blank":"越下越大","post":"。","options":["越下越大","越来越下大","下越大越"],"answer":0,"explanation":"越 + V + 越 + tính từ: càng… càng…"},{"context":"“Tiếng Trung của bạn ngày càng giỏi.”","pre":"你的汉语","blank":"越来越好","post":"了。","options":["越来越好","越来越很好","好越来越"],"answer":0,"explanation":"Khung cố định 越来越 + tính từ."},{"context":"Động từ hành động thường KHÔNG dùng trực tiếp với 越来越.","pre":"他","blank":"越来越想","post":"回家。","options":["越来越想","越来越回","越来越去"],"answer":0,"explanation":"Dùng với động từ tâm lý (想, 喜欢, 爱…)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气越来越很冷。","isCorrect":false,"correctVersion":"天气越来越冷。","explanation":"越来越 không dùng kèm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨越下越大。","isCorrect":true,"explanation":"越 + động từ + 越 + tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我越来越喜欢很汉语。","isCorrect":false,"correctVersion":"我越来越喜欢汉语。","explanation":"Không chen 很 vào giữa."},{"type":"sort","context":"Sắp xếp: “Thời tiết ngày càng nóng.”","words":["天气","越来越","热","了","。"],"answer":"天气越来越热了。","explanation":"越来越 + tính từ + 了."},{"type":"sort","context":"Sắp xếp: “Tôi ngày càng thích thành phố này.”","words":["我","越来越","喜欢","这个","城市","了","。"],"answer":"我越来越喜欢这个城市了。","explanation":"越来越 + động từ tâm lý."},{"type":"sort","context":"Sắp xếp: “Mưa càng lúc càng to.”","words":["雨","越","下","越","大","了","。"],"answer":"雨越下越大了。","explanation":"越…越… nhấn mạnh hai vế cùng tăng."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 越来越.","promptLang":"vi","prompt":"Tiếng Trung của bạn ngày càng giỏi.","answer":"你的汉语越来越好了。","answerPy":"Nǐ de Hànyǔ yuèláiyuè hǎo le.","explanation":"越来越 + tính từ + 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 越来越.","promptLang":"vi","prompt":"Tôi ngày càng thích món ăn Trung Quốc.","answer":"我越来越喜欢中国菜了。","answerPy":"Wǒ yuèláiyuè xǐhuan Zhōngguó cài le.","explanation":"Động từ tâm lý 喜欢."}]}],"/lessons/hsk3-bai-6.html":[{"point":"Bổ ngữ khả năng 「V + 得/不 + bổ ngữ」","items":[{"context":"“Tôi nghe không hiểu.”","pre":"老师说的话我","blank":"听不懂","post":"。","options":["听不懂","听得不懂","不听懂"],"answer":0,"explanation":"Phủ định: V + 不 + bổ ngữ (không chen 得)."},{"context":"“Chữ này tôi nhìn rõ.”","pre":"这个字我","blank":"看得清楚","post":"。","options":["看得清楚","看清楚得","得看清楚"],"answer":0,"explanation":"Khẳng định: V + 得 + bổ ngữ."},{"context":"“Nhiều đồ ăn thế này tôi ăn không hết.”","pre":"这么多菜我","blank":"吃不完","post":"。","options":["吃不完","吃得不完","不吃完"],"answer":0,"explanation":"V + 不 + 完 = không thể ăn hết."},{"context":"Hỏi chính phản: “Bạn nhìn rõ không?”","pre":"你","blank":"看得清楚看不清楚","post":"？","options":["看得清楚看不清楚","看得清楚吗不","不看得清楚吗"],"answer":0,"explanation":"Mẫu chính phản của bổ ngữ khả năng."},{"context":"Không được PHÉP làm thì dùng 不能, không dùng bổ ngữ khả năng.","pre":"这儿","blank":"不能","post":"抽烟。","options":["不能","抽不了","不抽得"],"answer":0,"explanation":"不能 = không được phép; 抽不了 = không thể hút (vì lý do khách quan)."},{"context":"“Bài này tôi làm được.”","pre":"这个题我","blank":"做得出来","post":"。","options":["做得出来","做出来得","得做出来"],"answer":0,"explanation":"V + 得 + bổ ngữ xu hướng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我听得不懂。","isCorrect":false,"correctVersion":"我听不懂。","explanation":"Phủ định là V + 不 + bổ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这么多菜我吃不完。","isCorrect":true,"explanation":"吃不完 = không thể ăn hết."},{"type":"judge","context":"Xét câu sau đúng hay sai (ý: nơi này cấm hút thuốc).","sentence":"这儿抽不了烟。","isCorrect":false,"correctVersion":"这儿不能抽烟。","explanation":"Cấm/không được phép thì dùng 不能."},{"type":"sort","context":"Sắp xếp: “Lời thầy nói tôi nghe không hiểu.”","words":["老师","说","的","话","我","听","不","懂","。"],"answer":"老师说的话我听不懂。","explanation":"Chủ đề hoá tân ngữ + V不懂."},{"type":"sort","context":"Sắp xếp: “Chữ trên bảng bạn nhìn rõ không?”","words":["黑板","上","的","字","你","看","得","清楚","吗","？"],"answer":"黑板上的字你看得清楚吗？","explanation":"V + 得 + bổ ngữ + 吗."},{"type":"sort","context":"Sắp xếp: “Nhiều đồ thế này tôi mang không nổi.”","words":["这么","多","东西","我","拿","不","了","。"],"answer":"这么多东西我拿不了。","explanation":"拿不了 = không mang nổi."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ khả năng.","promptLang":"vi","prompt":"Anh ấy nói nhanh quá, tôi nghe không hiểu.","answer":"他说得太快了，我听不懂。","answerPy":"Tā shuō de tài kuài le, wǒ tīng bù dǒng.","explanation":"听不懂 = nghe mà không hiểu được."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ khả năng.","promptLang":"vi","prompt":"Nhiều bài tập thế này tôi làm không xong.","answer":"这么多作业我做不完。","answerPy":"Zhème duō zuòyè wǒ zuò bù wán.","explanation":"做不完 = không thể làm hết."}]},{"point":"「呢」 hỏi vị trí: 「Danh từ + 呢？」","items":[{"context":"“Điện thoại của tôi đâu rồi?”","pre":"我的手机","blank":"呢","post":"？","options":["呢","吗","吧"],"answer":0,"explanation":"Danh từ + 呢 = hỏi vị trí, rất gọn trong khẩu ngữ."},{"context":"“Còn sách của bạn thì sao?” (hỏi lại)","pre":"你的书","blank":"呢","post":"？","options":["呢","吗","啊"],"answer":0,"explanation":"呢 cũng dùng hỏi lại cùng nội dung."},{"context":"Hỏi có/không vẫn dùng 吗.","pre":"你看见我的手机了","blank":"吗","post":"？","options":["吗","呢","吧"],"answer":0,"explanation":"呢 không dùng cho câu hỏi đúng–sai."},{"context":"“Bố mẹ bạn đâu rồi?”","pre":"你爸爸妈妈","blank":"呢","post":"？","options":["呢","吗","了"],"answer":0,"explanation":"Hỏi người ở đâu cũng dùng 呢."},{"context":"“Thầy giáo đang làm gì đấy?”","pre":"老师在做什么","blank":"呢","post":"？","options":["呢","吗","吧"],"answer":0,"explanation":"在…呢 nhấn mạnh việc đang diễn ra."},{"context":"“Tôi tìm mãi không thấy, chìa khoá đâu nhỉ?”","pre":"我找了半天，钥匙","blank":"呢","post":"？","options":["呢","吗","啊吗"],"answer":0,"explanation":"Dùng khi đang tìm đồ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"呢我的手机？","isCorrect":false,"correctVersion":"我的手机呢？","explanation":"呢 đứng cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai (ý: hỏi bạn có nhìn thấy điện thoại không).","sentence":"你看见我的手机了呢？","isCorrect":false,"correctVersion":"你看见我的手机了吗？","explanation":"Câu hỏi đúng–sai dùng 吗."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我很好，你呢？","isCorrect":true,"explanation":"呢 hỏi lại cùng nội dung."},{"type":"sort","context":"Sắp xếp: “Tôi tìm mãi, chìa khoá đâu nhỉ?”","words":["我","找","了","半天","，","钥匙","呢","？"],"answer":"我找了半天，钥匙呢？","explanation":"Danh từ + 呢."},{"type":"sort","context":"Sắp xếp: “Tôi đã làm xong rồi, còn bạn?”","words":["我","做","完","了","，","你","呢","？"],"answer":"我做完了，你呢？","explanation":"呢 hỏi lại."},{"type":"sort","context":"Sắp xếp: “Thầy đang làm gì đấy?”","words":["老师","在","做","什么","呢","？"],"answer":"老师在做什么呢？","explanation":"在 + động từ + 呢."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 呢 hỏi vị trí.","promptLang":"vi","prompt":"Điện thoại của tôi đâu rồi?","answer":"我的手机呢？","answerPy":"Wǒ de shǒujī ne?","explanation":"Danh từ + 呢."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi làm xong rồi, còn bạn thì sao?","answer":"我做完了，你呢？","answerPy":"Wǒ zuò wán le, nǐ ne?","explanation":"呢 hỏi lại cho gọn."}]},{"point":"「刚」 và 「刚才」 — hai cách nói VỪA MỚI","items":[{"context":"“Tôi vừa đến được năm phút.” (kèm khoảng thời gian)","pre":"我","blank":"刚","post":"来五分钟。","options":["刚","刚才","刚刚才"],"answer":0,"explanation":"刚 (phó từ) có thể đi kèm khoảng thời gian."},{"context":"“Vừa nãy thầy có gọi bạn đấy.”","pre":"","blank":"刚才","post":"老师叫你了。","options":["刚才","刚","刚了"],"answer":0,"explanation":"刚才 là DANH TỪ chỉ thời gian, đứng đầu câu được."},{"context":"“Anh ấy vừa đi ra ngoài.”","pre":"他","blank":"刚","post":"出去。","options":["刚","刚才的","才刚了"],"answer":0,"explanation":"刚 + động từ, đứng ngay trước động từ."},{"context":"刚才 thường đi với 了 vì chỉ việc ĐÃ xảy ra.","pre":"刚才我给你打电话","blank":"了","post":"。","options":["了","着","过"],"answer":0,"explanation":"刚才… + 了."},{"context":"Câu có 刚 thì thường KHÔNG dùng 了.","pre":"我","blank":"刚到","post":"，还没吃饭。","options":["刚到","刚到了","刚才到了的"],"answer":0,"explanation":"刚 nhấn mạnh việc vừa xảy ra, không cần 了."},{"context":"“Vừa nãy bạn nói gì cơ?”","pre":"","blank":"刚才","post":"你说什么？","options":["刚才","刚","刚的"],"answer":0,"explanation":"刚才 đứng đầu câu như trạng ngữ thời gian."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我刚才来五分钟。","isCorrect":false,"correctVersion":"我刚来五分钟。","explanation":"Đi với khoảng thời gian thì dùng 刚."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"刚才老师叫你了。","isCorrect":true,"explanation":"刚才 + câu có 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他刚的时候来了。","isCorrect":false,"correctVersion":"他刚才来了。","explanation":"刚 là phó từ, không dùng như danh từ thời gian."},{"type":"sort","context":"Sắp xếp: “Tôi vừa đến, chưa ăn cơm.”","words":["我","刚","到","，","还","没","吃饭","。"],"answer":"我刚到，还没吃饭。","explanation":"刚 + động từ, vế sau dùng 还没."},{"type":"sort","context":"Sắp xếp: “Vừa nãy tôi gọi điện cho bạn.”","words":["刚才","我","给","你","打","电话","了","。"],"answer":"刚才我给你打电话了。","explanation":"刚才 đứng đầu, câu có 了."},{"type":"sort","context":"Sắp xếp: “Anh ấy vừa mới ra ngoài.”","words":["他","刚","出去","。"],"answer":"他刚出去。","explanation":"刚 + động từ."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 刚 hay 刚才.","promptLang":"vi","prompt":"Tôi vừa đến được mười phút.","answer":"我刚来十分钟。","answerPy":"Wǒ gāng lái shí fēnzhōng.","explanation":"Có khoảng thời gian thì dùng 刚."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 刚 hay 刚才.","promptLang":"vi","prompt":"Vừa nãy bạn nói gì vậy?","answer":"刚才你说什么？","answerPy":"Gāngcái nǐ shuō shénme?","explanation":"刚才 là danh từ thời gian, đứng đầu câu."}]}],"/lessons/hsk3-bai-7.html":[{"point":"Bổ ngữ thời lượng — khoảng thời gian","items":[{"context":"“Tôi học tiếng Trung hai năm rồi.”","pre":"我","blank":"学了两年汉语","post":"。","options":["学了两年汉语","学了汉语两年","学汉语了两年"],"answer":0,"explanation":"V + 了 + thời lượng + tân ngữ."},{"context":"“Tôi xem tivi ba tiếng.”","pre":"我","blank":"看了三个小时电视","post":"。","options":["看了三个小时电视","看电视了三个小时","看了电视三个小时"],"answer":0,"explanation":"Thời lượng đứng TRƯỚC tân ngữ."},{"context":"“Tôi đợi anh ấy hai tiếng rồi.” (tân ngữ là người)","pre":"我","blank":"等了他两个小时","post":"了。","options":["等了他两个小时","等了两个小时他","等他了两个小时"],"answer":0,"explanation":"Tân ngữ là ĐẠI TỪ chỉ người thì đứng ngay sau động từ."},{"context":"“Tôi ngủ tám tiếng.”","pre":"我","blank":"睡了八个小时","post":"。","options":["睡了八个小时","睡觉了八个小时","睡了觉八个小时"],"answer":0,"explanation":"Từ ly hợp thì tách: 睡 + 了 + thời lượng (+ 觉)."},{"context":"“Anh ấy đã làm việc ở đây ba năm.”","pre":"他在这儿","blank":"工作了三年","post":"。","options":["工作了三年","工作三年了工作","了工作三年"],"answer":0,"explanation":"V + 了 + thời lượng."},{"context":"Muốn nói việc VẪN đang tiếp diễn thì thêm 了 ở cuối.","pre":"我学汉语学了两年","blank":"了","post":"。","options":["了","过","着"],"answer":0,"explanation":"…了…了 = đã kéo dài và còn tiếp tục."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我学了汉语两年。","isCorrect":false,"correctVersion":"我学了两年汉语。","explanation":"Thời lượng đứng trước tân ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我等了他两个小时。","isCorrect":true,"explanation":"Tân ngữ là đại từ người thì đứng ngay sau động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我看电视了三个小时。","isCorrect":false,"correctVersion":"我看了三个小时电视。","explanation":"了 ngay sau động từ, rồi mới đến thời lượng."},{"type":"sort","context":"Sắp xếp: “Tôi học tiếng Trung hai năm rồi.”","words":["我","学","了","两","年","汉语","了","。"],"answer":"我学了两年汉语了。","explanation":"…了…了 = vẫn đang tiếp tục."},{"type":"sort","context":"Sắp xếp: “Hôm qua tôi ngủ chín tiếng.”","words":["昨天","我","睡","了","九","个","小时","。"],"answer":"昨天我睡了九个小时。","explanation":"V + 了 + thời lượng."},{"type":"sort","context":"Sắp xếp: “Anh ấy làm việc ở Bắc Kinh ba năm.”","words":["他","在","北京","工作","了","三","年","。"],"answer":"他在北京工作了三年。","explanation":"Nơi chốn trước động từ, thời lượng sau 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ thời lượng.","promptLang":"vi","prompt":"Tôi học tiếng Trung được hai năm rồi.","answer":"我学了两年汉语了。","answerPy":"Wǒ xué le liǎng nián Hànyǔ le.","explanation":"Hai chữ 了 cho biết việc vẫn tiếp diễn."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ thời lượng.","promptLang":"vi","prompt":"Tôi đợi bạn nửa tiếng rồi.","answer":"我等了你半个小时了。","answerPy":"Wǒ děng le nǐ bàn ge xiǎoshí le.","explanation":"Tân ngữ người đứng ngay sau động từ."}]},{"point":"「对……感兴趣 / 有兴趣」 — nói về sự hứng thú","items":[{"context":"“Tôi rất hứng thú với văn hoá Trung Quốc.”","pre":"我","blank":"对中国文化","post":"很感兴趣。","options":["对中国文化","中国文化对","感兴趣中国文化"],"answer":0,"explanation":"对 + đối tượng + 感兴趣."},{"context":"“Anh ấy không hứng thú với bóng đá.”","pre":"他","blank":"对足球不感兴趣","post":"。","options":["对足球不感兴趣","不对足球感兴趣","对不足球感兴趣"],"answer":0,"explanation":"不 đứng trước 感兴趣."},{"context":"Cách nói tương đương: 有兴趣.","pre":"我","blank":"对中国菜很有兴趣","post":"。","options":["对中国菜很有兴趣","很有兴趣中国菜","对很有兴趣中国菜"],"answer":0,"explanation":"对 + đối tượng + 有兴趣."},{"context":"“Bạn có hứng thú với môn học này không?”","pre":"你","blank":"对这门课感兴趣","post":"吗？","options":["对这门课感兴趣","感兴趣对这门课","这门课对感兴趣"],"answer":0,"explanation":"Giữ nguyên trật tự khi hỏi."},{"context":"Mức độ mạnh: thêm 非常 trước 感兴趣.","pre":"我对音乐","blank":"非常感兴趣","post":"。","options":["非常感兴趣","感兴趣非常","非常有感兴趣"],"answer":0,"explanation":"Phó từ mức độ đứng trước 感兴趣."},{"context":"Nói THÍCH làm gì thì dùng 喜欢 + động từ.","pre":"我","blank":"喜欢","post":"看中国电影。","options":["喜欢","对","感兴趣"],"answer":0,"explanation":"喜欢 + động từ; 感兴趣 cần giới từ 对 + danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我感兴趣中国文化。","isCorrect":false,"correctVersion":"我对中国文化感兴趣。","explanation":"Thiếu giới từ 对."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他对足球不感兴趣。","isCorrect":true,"explanation":"不 đứng trước 感兴趣 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我很有兴趣中国菜。","isCorrect":false,"correctVersion":"我对中国菜很有兴趣。","explanation":"对 + đối tượng + 有兴趣."},{"type":"sort","context":"Sắp xếp: “Tôi rất hứng thú với lịch sử Trung Quốc.”","words":["我","对","中国","历史","很","感兴趣","。"],"answer":"我对中国历史很感兴趣。","explanation":"对 + đối tượng + 很 + 感兴趣."},{"type":"sort","context":"Sắp xếp: “Bạn có hứng thú với môn này không?”","words":["你","对","这门课","感兴趣","吗","？"],"answer":"你对这门课感兴趣吗？","explanation":"Câu hỏi giữ nguyên trật tự."},{"type":"sort","context":"Sắp xếp: “Anh ấy rất hứng thú với âm nhạc.”","words":["他","对","音乐","非常","感兴趣","。"],"answer":"他对音乐非常感兴趣。","explanation":"非常 tăng mức độ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 对……感兴趣.","promptLang":"vi","prompt":"Tôi rất hứng thú với văn hoá Trung Quốc.","answer":"我对中国文化很感兴趣。","answerPy":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","explanation":"Khung 对…感兴趣."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 对……感兴趣.","promptLang":"vi","prompt":"Anh ấy không hứng thú với bóng đá.","answer":"他对足球不感兴趣。","answerPy":"Tā duì zúqiú bù gǎn xìngqù.","explanation":"不 trước 感兴趣."}]},{"point":"Dùng 「半」「刻」「差」 để nói giờ","items":[{"context":"“2 giờ rưỡi”","pre":"","blank":"两点半","post":"","options":["两点半","两点三十半","半两点"],"answer":0,"explanation":"半 = 30 phút, đứng sau 点."},{"context":"“2 giờ 15”","pre":"","blank":"两点一刻","post":"","options":["两点一刻","一刻两点","两刻一点"],"answer":0,"explanation":"一刻 = 15 phút."},{"context":"“2 giờ 45”","pre":"","blank":"两点三刻","post":"","options":["两点三刻","三刻两点","两点三十五"],"answer":0,"explanation":"三刻 = 45 phút."},{"context":"“Còn 5 phút nữa là 2 giờ” (1 giờ 55)","pre":"","blank":"差五分两点","post":"","options":["差五分两点","两点差五分钟的","五分差两点"],"answer":0,"explanation":"差 + số phút + giờ."},{"context":"“7 giờ kém 10”","pre":"","blank":"差十分七点","post":"","options":["差十分七点","七点差十分的","十分差七点"],"answer":0,"explanation":"Khung 差…点 rất hay dùng trong khẩu ngữ."},{"context":"“Bây giờ mấy giờ rồi?”","pre":"现在","blank":"几点了","post":"？","options":["几点了","几点吗","多少点了"],"answer":0,"explanation":"了 cho biết hỏi về thời điểm hiện tại."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在两点三十半。","isCorrect":false,"correctVersion":"现在两点半。","explanation":"半 đã là 30 phút."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"差五分两点我就到了。","isCorrect":true,"explanation":"差 + phút + giờ, đúng khung khẩu ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们一刻两点见吧。","isCorrect":false,"correctVersion":"我们两点一刻见吧。","explanation":"Giờ trước, phút sau."},{"type":"sort","context":"Sắp xếp: “Chúng ta gặp nhau lúc 2 giờ rưỡi nhé.”","words":["我们","两点半","见","吧","。"],"answer":"我们两点半见吧。","explanation":"Thời gian trước động từ."},{"type":"sort","context":"Sắp xếp: “Tôi 7 giờ kém 15 ra khỏi nhà.”","words":["我","差","一刻","七点","出门","。"],"answer":"我差一刻七点出门。","explanation":"差一刻七点 = 6 giờ 45."},{"type":"sort","context":"Sắp xếp: “Lớp học bắt đầu lúc 8 giờ 15.”","words":["八点","一刻","开始","上课","。"],"answer":"八点一刻开始上课。","explanation":"Thời gian đứng đầu câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bây giờ là 2 giờ rưỡi.","answer":"现在两点半。","answerPy":"Xiànzài liǎng diǎn bàn.","explanation":"两点半 = 2 giờ 30."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 差.","promptLang":"vi","prompt":"Còn năm phút nữa là 8 giờ.","answer":"差五分八点。","answerPy":"Chà wǔ fēn bā diǎn.","explanation":"差 + phút + giờ."}]}],"/lessons/hsk3-bai-8.html":[{"point":"「又」 và 「再」 — hai cách nói LẠI","items":[{"context":"“Hôm qua anh ấy lại đến.” (đã xảy ra)","pre":"昨天他","blank":"又","post":"来了。","options":["又","再","还"],"answer":0,"explanation":"又 dùng cho việc ĐÃ lặp lại."},{"context":"“Ngày mai tôi lại đến.” (chưa xảy ra)","pre":"明天我","blank":"再","post":"来。","options":["再","又","还是"],"answer":0,"explanation":"再 dùng cho việc SẼ lặp lại."},{"context":"“Xin nói lại một lần nữa.”","pre":"请你","blank":"再","post":"说一遍。","options":["再","又","还"],"answer":0,"explanation":"Đề nghị việc sắp làm → 再."},{"context":"“Anh ấy lại quên nữa rồi.”","pre":"他","blank":"又","post":"忘了。","options":["又","再","还"],"answer":0,"explanation":"Việc vừa lặp lại, đã xảy ra → 又."},{"context":"“Uống thêm một cốc nữa nhé.”","pre":"","blank":"再","post":"喝一杯吧。","options":["再","又","还有"],"answer":0,"explanation":"Mời/đề nghị việc sắp xảy ra → 再."},{"context":"“Hôm nay lại mưa rồi.”","pre":"今天","blank":"又","post":"下雨了。","options":["又","再","还"],"answer":0,"explanation":"Đã xảy ra, kèm 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"昨天他再来了。","isCorrect":false,"correctVersion":"昨天他又来了。","explanation":"Việc đã xảy ra dùng 又."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"请你再说一遍。","isCorrect":true,"explanation":"Đề nghị việc sắp làm dùng 再."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"明天我又来看你。","isCorrect":false,"correctVersion":"明天我再来看你。","explanation":"Việc chưa xảy ra dùng 再."},{"type":"sort","context":"Sắp xếp: “Hôm nay anh ấy lại đến muộn.”","words":["今天","他","又","迟到","了","。"],"answer":"今天他又迟到了。","explanation":"又 + động từ + 了."},{"type":"sort","context":"Sắp xếp: “Ngày mai tôi lại đến thăm bạn.”","words":["明天","我","再","来","看","你","。"],"answer":"明天我再来看你。","explanation":"再 cho việc chưa xảy ra."},{"type":"sort","context":"Sắp xếp: “Xin thầy nói lại một lần nữa.”","words":["老师","，","请","您","再","说","一","遍","。"],"answer":"老师，请您再说一遍。","explanation":"请 + 您 + 再 + động từ."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 又 hay 再.","promptLang":"vi","prompt":"Hôm qua anh ấy lại đến muộn.","answer":"昨天他又迟到了。","answerPy":"Zuótiān tā yòu chídào le.","explanation":"Đã xảy ra → 又."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 又 hay 再.","promptLang":"vi","prompt":"Xin bạn nói lại một lần nữa.","answer":"请你再说一遍。","answerPy":"Qǐng nǐ zài shuō yí biàn.","explanation":"Chưa xảy ra → 再."}]},{"point":"Đại từ nghi vấn dùng linh hoạt 「疑问代词 + 就 + 疑问代词」","items":[{"context":"“Bạn muốn ăn gì thì tôi nấu món đó.”","pre":"你想吃什么，我","blank":"就做什么","post":"。","options":["就做什么","就做那个","做什么就"],"answer":0,"explanation":"Vế sau LẶP LẠI đúng từ để hỏi, thêm 就."},{"context":"“Bạn đi đâu tôi đi đó.”","pre":"你去哪儿，我","blank":"就去哪儿","post":"。","options":["就去哪儿","也去那儿就","去哪儿就"],"answer":0,"explanation":"哪儿…就…哪儿."},{"context":"“Ai muốn đi thì người đó đi.”","pre":"谁想去，","blank":"谁就去","post":"。","options":["谁就去","就谁去","那个人就去"],"answer":0,"explanation":"谁…谁就… (cùng một người)."},{"context":"“Bạn làm thế nào thì tôi làm thế ấy.”","pre":"你怎么做，我","blank":"就怎么做","post":"。","options":["就怎么做","就那样做","怎么做就"],"answer":0,"explanation":"怎么…就怎么…"},{"context":"“Cái nào rẻ thì mua cái đó.”","pre":"哪个便宜，","blank":"就买哪个","post":"。","options":["就买哪个","就买那个","买哪个就"],"answer":0,"explanation":"哪个…就…哪个."},{"context":"“Bao nhiêu tiền cũng được, bạn cứ mua đi.”","pre":"多少钱都","blank":"行","post":"，你买吧。","options":["行","就行哪个","都可以吗"],"answer":0,"explanation":"多少…都… = bao nhiêu cũng được."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你想吃什么，我就做那个。","isCorrect":false,"correctVersion":"你想吃什么，我就做什么。","explanation":"Phải lặp lại đúng từ để hỏi ở vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"谁想去，谁就去。","isCorrect":true,"explanation":"谁…谁就… chỉ cùng một đối tượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你去哪儿我也去哪儿就。","isCorrect":false,"correctVersion":"你去哪儿，我就去哪儿。","explanation":"就 đứng trước động từ ở vế sau."},{"type":"sort","context":"Sắp xếp: “Bạn muốn ăn gì tôi nấu món đó.”","words":["你","想","吃","什么","，","我","就","做","什么","。"],"answer":"你想吃什么，我就做什么。","explanation":"什么…就…什么."},{"type":"sort","context":"Sắp xếp: “Cái nào rẻ thì tôi mua cái đó.”","words":["哪个","便宜","，","我","就","买","哪个","。"],"answer":"哪个便宜，我就买哪个。","explanation":"哪个…就…哪个."},{"type":"sort","context":"Sắp xếp: “Bạn làm thế nào tôi làm thế ấy.”","words":["你","怎么","做","，","我","就","怎么","做","。"],"answer":"你怎么做，我就怎么做。","explanation":"怎么…就怎么…"},{"type":"translate","context":"Dịch sang tiếng Trung, dùng khung 疑问代词 + 就 + 疑问代词.","promptLang":"vi","prompt":"Bạn đi đâu thì tôi đi đó.","answer":"你去哪儿，我就去哪儿。","answerPy":"Nǐ qù nǎr, wǒ jiù qù nǎr.","explanation":"哪儿…就…哪儿."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng khung 疑问代词 + 就 + 疑问代词.","promptLang":"vi","prompt":"Ai muốn đi thì người đó đi.","answer":"谁想去，谁就去。","answerPy":"Shéi xiǎng qù, shéi jiù qù.","explanation":"谁…谁就…"}]}],"/lessons/hsk3-bai-9.html":[{"point":"「越A越B」 — B thay đổi theo A","items":[{"context":"“Mưa càng lúc càng to.”","pre":"雨","blank":"越下越大","post":"。","options":["越下越大","越大越下","越来越下大"],"answer":0,"explanation":"越 + ĐỘNG TỪ + 越 + TÍNH TỪ."},{"context":"“Anh ấy càng nói càng nhanh.”","pre":"他","blank":"越说越快","post":"。","options":["越说越快","越说越很快","越快越说"],"answer":0,"explanation":"Không thêm 很 vào khung 越…越…"},{"context":"“Càng học càng thấy thú vị.”","pre":"汉语","blank":"越学越有意思","post":"。","options":["越学越有意思","越有意思越学","越来越学有意思"],"answer":0,"explanation":"Vế trước là việc làm, vế sau là kết quả thay đổi."},{"context":"Chỉ nói mức độ TĂNG DẦN theo thời gian thì dùng 越来越.","pre":"天气","blank":"越来越冷","post":"了。","options":["越来越冷","越冷越","越天气越冷"],"answer":0,"explanation":"越来越 + tính từ; 越A越B cần hai vế A, B."},{"context":"“Bạn càng nói tôi càng không hiểu.”","pre":"你越说，我","blank":"越不明白","post":"。","options":["越不明白","不越明白","越明白不"],"answer":0,"explanation":"Hai vế có chủ ngữ khác nhau thì mỗi vế một 越."},{"context":"“Càng nhiều người càng vui.”","pre":"","blank":"人越多越热闹","post":"。","options":["人越多越热闹","人越热闹越多","越人多越热闹"],"answer":0,"explanation":"越 đứng sau chủ ngữ, trước tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨越大越下。","isCorrect":false,"correctVersion":"雨越下越大。","explanation":"越 + động từ + 越 + tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他越说越快。","isCorrect":true,"explanation":"Đúng khung 越A越B, không thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气越冷了。","isCorrect":false,"correctVersion":"天气越来越冷了。","explanation":"Chỉ có một vế thì phải dùng 越来越."},{"type":"sort","context":"Sắp xếp: “Mưa càng lúc càng to.”","words":["雨","越","下","越","大","了","。"],"answer":"雨越下越大了。","explanation":"越下越大 + 了."},{"type":"sort","context":"Sắp xếp: “Tiếng Trung càng học càng thú vị.”","words":["汉语","越","学","越","有意思","。"],"answer":"汉语越学越有意思。","explanation":"Chủ đề + 越 + V + 越 + tính từ."},{"type":"sort","context":"Sắp xếp: “Bạn càng nói tôi càng không hiểu.”","words":["你","越","说","，","我","越","不","明白","。"],"answer":"你越说，我越不明白。","explanation":"Hai chủ ngữ khác nhau, mỗi vế một 越."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 越……越…….","promptLang":"vi","prompt":"Anh ấy càng nói càng nhanh.","answer":"他越说越快。","answerPy":"Tā yuè shuō yuè kuài.","explanation":"越 + động từ + 越 + tính từ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 越……越…….","promptLang":"vi","prompt":"Càng đông người càng vui.","answer":"人越多越热闹。","answerPy":"Rén yuè duō yuè rènao.","explanation":"越多越热闹."}]},{"point":"Câu so sánh bằng 「A 跟 B 一样」","items":[{"context":"“Tôi cao bằng anh ấy.”","pre":"我","blank":"跟他一样高","post":"。","options":["跟他一样高","跟他一样很高","一样跟他高"],"answer":0,"explanation":"A + 跟 + B + 一样 + tính từ, KHÔNG thêm 很."},{"context":"“Chiếc áo này giống chiếc kia.”","pre":"这件衣服","blank":"跟那件一样","post":"。","options":["跟那件一样","一样跟那件","跟一样那件"],"answer":0,"explanation":"一样 có thể đứng cuối khi không nêu tính từ."},{"context":"Phủ định: “Tôi không cao bằng anh ấy.”","pre":"我","blank":"跟他不一样高","post":"。","options":["跟他不一样高","不跟他一样高","跟不他一样高"],"answer":0,"explanation":"不 đứng ngay trước 一样."},{"context":"“Tiếng Trung của bạn giỏi như người Trung Quốc.”","pre":"你的汉语","blank":"跟中国人一样好","post":"。","options":["跟中国人一样好","一样中国人跟好","跟中国人好一样"],"answer":0,"explanation":"Khung cố định A 跟 B 一样 + tính từ."},{"context":"So sánh HƠN thì dùng 比.","pre":"他","blank":"比我高","post":"。","options":["比我高","跟我一样高一点儿","比我一样高"],"answer":0,"explanation":"比 dùng khi hai bên KHÁC nhau; 跟…一样 khi bằng nhau."},{"context":"Câu hỏi: “Bạn cao bằng anh ấy không?”","pre":"你","blank":"跟他一样高吗","post":"？","options":["跟他一样高吗","跟他一样吗高","一样跟他高吗"],"answer":0,"explanation":"Thêm 吗 vào cuối câu so sánh bằng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我跟他一样很高。","isCorrect":false,"correctVersion":"我跟他一样高。","explanation":"一样 đã nêu mức độ, không thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服跟那件不一样。","isCorrect":true,"explanation":"不 đứng trước 一样 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我一样跟他高。","isCorrect":false,"correctVersion":"我跟他一样高。","explanation":"Trật tự: A 跟 B 一样 + tính từ."},{"type":"sort","context":"Sắp xếp: “Tôi cao bằng anh trai tôi.”","words":["我","跟","我","哥哥","一样","高","。"],"answer":"我跟我哥哥一样高。","explanation":"A 跟 B 一样 + tính từ."},{"type":"sort","context":"Sắp xếp: “Chiếc áo này không giống chiếc kia.”","words":["这","件","衣服","跟","那","件","不","一样","。"],"answer":"这件衣服跟那件不一样。","explanation":"不一样 = không giống."},{"type":"sort","context":"Sắp xếp: “Tiếng Trung của bạn giỏi như người Trung Quốc.”","words":["你","的","汉语","跟","中国人","一样","好","。"],"answer":"你的汉语跟中国人一样好。","explanation":"Cụm danh từ + 跟…一样 + tính từ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 跟……一样.","promptLang":"vi","prompt":"Tôi cao bằng anh ấy.","answer":"我跟他一样高。","answerPy":"Wǒ gēn tā yíyàng gāo.","explanation":"Không thêm 很 vào sau 一样."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 跟……不一样.","promptLang":"vi","prompt":"Món này không giống món hôm qua.","answer":"这个菜跟昨天的不一样。","answerPy":"Zhège cài gēn zuótiān de bù yíyàng.","explanation":"不 đứng trước 一样."}]}],"/lessons/hsk3-bai-10.html":[{"point":"Câu so sánh (2): 「A 比 B + tính từ + 一点儿/得多」","items":[{"context":"“Anh ấy cao hơn tôi.”","pre":"他","blank":"比我高","post":"。","options":["比我高","比我很高","跟我一样高"],"answer":0,"explanation":"Câu chữ 比 không dùng 很, 非常 trước tính từ."},{"context":"“Anh ấy cao hơn tôi một chút.”","pre":"他比我","blank":"高一点儿","post":"。","options":["高一点儿","很高一点儿","一点儿高"],"answer":0,"explanation":"Chênh lệch NHỎ: tính từ + 一点儿/一些."},{"context":"“Anh ấy cao hơn tôi nhiều.”","pre":"他比我","blank":"高得多","post":"。","options":["高得多","很高多","多高得"],"answer":0,"explanation":"Chênh lệch LỚN: tính từ + 得多/多了."},{"context":"“Anh ấy hơn tôi ba tuổi.”","pre":"他比我","blank":"大三岁","post":"。","options":["大三岁","三岁大","大得三岁"],"answer":0,"explanation":"Chênh lệch cụ thể đứng ngay sau tính từ."},{"context":"Phủ định: “Tôi không cao bằng anh ấy.”","pre":"我","blank":"没有他高","post":"。","options":["没有他高","不比他高很","比他不高"],"answer":0,"explanation":"Phủ định câu so sánh thường dùng 没有 + B + tính từ."},{"context":"“Hôm nay lạnh hơn hôm qua nhiều.”","pre":"今天","blank":"比昨天冷多了","post":"。","options":["比昨天冷多了","比昨天很冷了","跟昨天冷多了"],"answer":0,"explanation":"冷多了 = lạnh hơn nhiều."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他比我很高。","isCorrect":false,"correctVersion":"他比我高。","explanation":"Câu 比 không dùng 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他比我大三岁。","isCorrect":true,"explanation":"Chênh lệch cụ thể đứng sau tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件比那件便宜一点儿多了。","isCorrect":false,"correctVersion":"这件比那件便宜得多。","explanation":"Không dùng đồng thời hai mức chênh lệch."},{"type":"sort","context":"Sắp xếp: “Anh ấy hơn tôi ba tuổi.”","words":["他","比","我","大","三","岁","。"],"answer":"他比我大三岁。","explanation":"A 比 B + tính từ + chênh lệch."},{"type":"sort","context":"Sắp xếp: “Hôm nay lạnh hơn hôm qua nhiều.”","words":["今天","比","昨天","冷","多","了","。"],"answer":"今天比昨天冷多了。","explanation":"冷多了 = chênh lệch lớn."},{"type":"sort","context":"Sắp xếp: “Chiếc áo này rẻ hơn chiếc kia một chút.”","words":["这","件","衣服","比","那","件","便宜","一点儿","。"],"answer":"这件衣服比那件便宜一点儿。","explanation":"一点儿 = chênh lệch nhỏ."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 比.","promptLang":"vi","prompt":"Anh ấy cao hơn tôi nhiều.","answer":"他比我高得多。","answerPy":"Tā bǐ wǒ gāo de duō.","explanation":"得多 = hơn nhiều."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 比.","promptLang":"vi","prompt":"Hôm nay nóng hơn hôm qua một chút.","answer":"今天比昨天热一点儿。","answerPy":"Jīntiān bǐ zuótiān rè yìdiǎnr.","explanation":"一点儿 = hơn một chút."}]},{"point":"Số ước lượng (1): hai số liên tiếp ghép lại","items":[{"context":"“ba bốn người”","pre":"","blank":"三四个人","post":"","options":["三四个人","三和四个人","三或四个人"],"answer":0,"explanation":"Hai số LIỀN NHAU ghép trực tiếp, không cần 和."},{"context":"“năm sáu ngày”","pre":"","blank":"五六天","post":"","options":["五六天","五七天","五和六天"],"answer":0,"explanation":"Chỉ ghép hai số liền nhau."},{"context":"“mười mấy người”","pre":"","blank":"十几个人","post":"","options":["十几个人","几十个人","十多几个人"],"answer":0,"explanation":"十几 = 11–19; 几十 = mấy chục."},{"context":"“mấy chục quyển sách”","pre":"","blank":"几十本书","post":"","options":["几十本书","十几本书","几本十书"],"answer":0,"explanation":"几十 = 20–90."},{"context":"“hai mươi mấy người”","pre":"","blank":"二十几个人","post":"","options":["二十几个人","十几二十个人","几二十个人"],"answer":0,"explanation":"二十几 = 21–29."},{"context":"“hơn một trăm tệ”","pre":"","blank":"一百多块","post":"","options":["一百多块","多一百块","一百几块"],"answer":0,"explanation":"多 đứng sau số tròn trăm."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"教室里有三和四个人。","isCorrect":false,"correctVersion":"教室里有三四个人。","explanation":"Số ước lượng ghép trực tiếp, không dùng 和."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我在北京住了五六天。","isCorrect":true,"explanation":"五六 là hai số liền nhau — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们班有十几二十个学生。","isCorrect":false,"correctVersion":"我们班有二十几个学生。","explanation":"Không ghép hai cách ước lượng khác nhau."},{"type":"sort","context":"Sắp xếp: “Trong phòng có ba bốn người.”","words":["房间","里","有","三四","个","人","。"],"answer":"房间里有三四个人。","explanation":"Số ước lượng + lượng từ + danh từ."},{"type":"sort","context":"Sắp xếp: “Tôi ở Bắc Kinh năm sáu ngày.”","words":["我","在","北京","住","了","五六","天","。"],"answer":"我在北京住了五六天。","explanation":"Thời lượng ước lượng sau 了."},{"type":"sort","context":"Sắp xếp: “Lớp chúng tôi có hai mươi mấy học sinh.”","words":["我们","班","有","二十几","个","学生","。"],"answer":"我们班有二十几个学生。","explanation":"二十几 = hai mươi mấy."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng số ước lượng.","promptLang":"vi","prompt":"Trong phòng có ba bốn người.","answer":"房间里有三四个人。","answerPy":"Fángjiān lǐ yǒu sān sì ge rén.","explanation":"三四 ghép trực tiếp."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng số ước lượng.","promptLang":"vi","prompt":"Tôi đợi khoảng năm sáu phút.","answer":"我等了五六分钟。","answerPy":"Wǒ děng le wǔ liù fēnzhōng.","explanation":"五六分钟 = khoảng 5-6 phút."}]}],"/lessons/hsk3-bai-11.html":[{"point":"Câu chữ 「把」(1): 「A 把 B + động từ + ……」","items":[{"context":"“Tôi đã đọc xong quyển sách đó.”","pre":"我","blank":"把那本书看完了","post":"。","options":["把那本书看完了","把那本书看","看完把那本书了"],"answer":0,"explanation":"Sau động từ phải có thành phần khác: 完了."},{"context":"“Bạn mang cái ghế này vào đi.”","pre":"你","blank":"把这个椅子拿进来","post":"吧。","options":["把这个椅子拿进来","把拿进来这个椅子","拿进来把这个椅子"],"answer":0,"explanation":"把 + tân ngữ xác định + động từ + bổ ngữ xu hướng."},{"context":"Phủ định: “Tôi chưa làm xong bài tập.”","pre":"我","blank":"没把作业做完","post":"。","options":["没把作业做完","把作业没做完","把没作业做完"],"answer":0,"explanation":"没/别/不 đứng TRƯỚC 把."},{"context":"Tân ngữ của 把 phải XÁC ĐỊNH.","pre":"请","blank":"把这杯水","post":"喝了。","options":["把这杯水","把一杯水","把水一杯"],"answer":0,"explanation":"这/那 + lượng từ + danh từ là vật xác định."},{"context":"“Đừng để quên điện thoại nhé.”","pre":"","blank":"别把手机忘了","post":"。","options":["别把手机忘了","把别手机忘了","把手机别忘了"],"answer":0,"explanation":"别 đứng trước 把."},{"context":"“Cô ấy đã dịch bài văn đó sang tiếng Việt.”","pre":"她","blank":"把那篇文章翻译成越南语了","post":"。","options":["把那篇文章翻译成越南语了","翻译成越南语把那篇文章了","把翻译那篇文章成越南语了"],"answer":0,"explanation":"把 + B + V + 成 + kết quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把书看。","isCorrect":false,"correctVersion":"我把书看完了。","explanation":"Sau động từ trong câu 把 phải có thành phần bổ sung."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我没把作业做完。","isCorrect":true,"explanation":"没 đứng trước 把 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把一本书拿来了。","isCorrect":false,"correctVersion":"我把那本书拿来了。","explanation":"Tân ngữ của 把 phải xác định."},{"type":"sort","context":"Sắp xếp: “Tôi đã đọc xong quyển sách đó.”","words":["我","把","那","本","书","看","完","了","。"],"answer":"我把那本书看完了。","explanation":"把 + tân ngữ + V + bổ ngữ + 了."},{"type":"sort","context":"Sắp xếp: “Bạn đừng quên điện thoại nhé.”","words":["你","别","把","手机","忘","了","。"],"answer":"你别把手机忘了。","explanation":"别 trước 把."},{"type":"sort","context":"Sắp xếp: “Mời bạn uống cốc nước này.”","words":["请","你","把","这","杯","水","喝","了","。"],"answer":"请你把这杯水喝了。","explanation":"Câu đề nghị với 把."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Tôi đã làm xong bài tập rồi.","answer":"我把作业做完了。","answerPy":"Wǒ bǎ zuòyè zuò wán le.","explanation":"把 + tân ngữ + V + 完 + 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Bạn đừng quên mang quyển sách đó nhé.","answer":"你别把那本书忘了。","answerPy":"Nǐ bié bǎ nà běn shū wàng le.","explanation":"别 + 把 + tân ngữ xác định."}]},{"point":"Số ước lượng (2): 「左右」","items":[{"context":"“khoảng ba mươi người”","pre":"","blank":"三十个人左右","post":"","options":["三十个人左右","左右三十个人","三十左右个人"],"answer":0,"explanation":"左右 đứng SAU cụm số lượng."},{"context":"“khoảng 2 giờ”","pre":"","blank":"两点左右","post":"","options":["两点左右","左右两点","两点左右钟"],"answer":0,"explanation":"左右 sau thời điểm."},{"context":"“khoảng 100 tệ”","pre":"","blank":"一百块左右","post":"","options":["一百块左右","左右一百块","一百多块左右"],"answer":0,"explanation":"Không dùng 多 cùng 左右."},{"context":"“khoảng nửa tiếng”","pre":"","blank":"半个小时左右","post":"","options":["半个小时左右","左右半个小时","半左右个小时"],"answer":0,"explanation":"左右 sau cụm thời lượng."},{"context":"Nói “hơn” (nhiều hơn con số) thì dùng 多.","pre":"教室里有","blank":"三十多","post":"个人。","options":["三十多","三十左右多","多三十"],"answer":0,"explanation":"多 = hơn; 左右 = xấp xỉ (có thể hơn hoặc kém)."},{"context":"“Tôi đợi khoảng mười phút.”","pre":"我等了","blank":"十分钟左右","post":"。","options":["十分钟左右","左右十分钟","十左右分钟"],"answer":0,"explanation":"Thời lượng + 左右."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"教室里有左右三十个人。","isCorrect":false,"correctVersion":"教室里有三十个人左右。","explanation":"左右 đứng sau cụm số lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们两点左右见吧。","isCorrect":true,"explanation":"两点左右 = khoảng 2 giờ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服三百多块左右。","isCorrect":false,"correctVersion":"这件衣服三百块左右。","explanation":"多 và 左右 không dùng cùng nhau."},{"type":"sort","context":"Sắp xếp: “Lớp có khoảng ba mươi học sinh.”","words":["班","里","有","三十","个","学生","左右","。"],"answer":"班里有三十个学生左右。","explanation":"左右 ở cuối cụm số lượng."},{"type":"sort","context":"Sắp xếp: “Chúng ta gặp nhau khoảng 2 giờ nhé.”","words":["我们","两点","左右","见","吧","。"],"answer":"我们两点左右见吧。","explanation":"Thời điểm + 左右."},{"type":"sort","context":"Sắp xếp: “Tôi đợi khoảng nửa tiếng.”","words":["我","等","了","半","个","小时","左右","。"],"answer":"我等了半个小时左右。","explanation":"Thời lượng + 左右."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 左右.","promptLang":"vi","prompt":"Chiếc áo này khoảng ba trăm tệ.","answer":"这件衣服三百块左右。","answerPy":"Zhè jiàn yīfu sānbǎi kuài zuǒyòu.","explanation":"Số tiền + 左右."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 左右.","promptLang":"vi","prompt":"Tôi đợi anh ấy khoảng mười phút.","answer":"我等了他十分钟左右。","answerPy":"Wǒ děng le tā shí fēnzhōng zuǒyòu.","explanation":"Thời lượng + 左右."}]}],"/lessons/hsk3-bai-12.html":[{"point":"Phân biệt 「才」 và 「就」","items":[{"context":"“Anh ấy 5 giờ đã dậy rồi.” (sớm hơn mong đợi)","pre":"他五点","blank":"就","post":"起床了。","options":["就","才","还"],"answer":0,"explanation":"就 = sớm/nhanh hơn dự kiến."},{"context":"“Mãi 8 giờ anh ấy mới đến.” (muộn hơn mong đợi)","pre":"他八点","blank":"才","post":"来。","options":["才","就","都"],"answer":0,"explanation":"才 = muộn/chậm hơn dự kiến."},{"context":"Câu có 才 thường KHÔNG dùng 了.","pre":"他昨天","blank":"才来","post":"。","options":["才来","才来了","就来了才"],"answer":0,"explanation":"才 nhấn mạnh muộn, không cần 了."},{"context":"“Tôi học một năm đã nói được rồi.”","pre":"我学了一年","blank":"就","post":"会说了。","options":["就","才","再"],"answer":0,"explanation":"就 nhấn mạnh nhanh, ít thời gian."},{"context":"“Tôi học ba năm mới nói được.”","pre":"我学了三年","blank":"才","post":"会说。","options":["才","就","还"],"answer":0,"explanation":"才 nhấn mạnh tốn nhiều thời gian."},{"context":"“Ăn cơm xong là tôi đi ngay.”","pre":"我吃了饭","blank":"就","post":"走。","options":["就","才","再说"],"answer":0,"explanation":"就 nối hai việc xảy ra liền nhau."},{"type":"judge","context":"Xét câu sau đúng hay sai (ý: mãi 8 giờ mới đến).","sentence":"他八点就来了。","isCorrect":false,"correctVersion":"他八点才来。","explanation":"Muộn hơn mong đợi thì dùng 才."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我学了一年就会说汉语了。","isCorrect":true,"explanation":"就 nhấn mạnh học nhanh — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他昨天才来了。","isCorrect":false,"correctVersion":"他昨天才来。","explanation":"Câu có 才 thường không dùng 了."},{"type":"sort","context":"Sắp xếp: “Anh ấy 5 giờ đã dậy rồi.”","words":["他","五点","就","起床","了","。"],"answer":"他五点就起床了。","explanation":"就 + động từ + 了."},{"type":"sort","context":"Sắp xếp: “Mãi 9 giờ anh ấy mới về nhà.”","words":["他","九点","才","回","家","。"],"answer":"他九点才回家。","explanation":"才 không kèm 了."},{"type":"sort","context":"Sắp xếp: “Tôi học ba năm mới nói được tiếng Trung.”","words":["我","学","了","三","年","才","会","说","汉语","。"],"answer":"我学了三年才会说汉语。","explanation":"才 nhấn mạnh tốn thời gian."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 就 hay 才.","promptLang":"vi","prompt":"Mãi 8 giờ anh ấy mới đến.","answer":"他八点才来。","answerPy":"Tā bā diǎn cái lái.","explanation":"Muộn hơn mong đợi → 才, không dùng 了."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 就 hay 才.","promptLang":"vi","prompt":"Tôi học nửa năm đã nói được rồi.","answer":"我学了半年就会说了。","answerPy":"Wǒ xué le bàn nián jiù huì shuō le.","explanation":"Nhanh hơn dự kiến → 就."}]},{"point":"Câu chữ 「把」(2): 「把 B + động từ + 在/到/给……」","items":[{"context":"“Tôi đặt sách lên bàn.”","pre":"我","blank":"把书放在桌子上","post":"。","options":["把书放在桌子上","放书在桌子上","把书在桌子上放"],"answer":0,"explanation":"把 + vật + V + 在 + nơi chốn."},{"context":"“Tôi gửi bức thư đó đến Bắc Kinh.”","pre":"我","blank":"把那封信寄到北京","post":"了。","options":["把那封信寄到北京","寄那封信到北京把","把寄那封信到北京"],"answer":0,"explanation":"把 + vật + V + 到 + đích đến."},{"context":"“Tôi đưa quyển sách cho anh ấy rồi.”","pre":"我","blank":"把书给他","post":"了。","options":["把书给他","给书把他","把给他书"],"answer":0,"explanation":"把 + vật + 给 + người."},{"context":"“Bạn để hành lý vào phòng nhé.”","pre":"你","blank":"把行李放到房间里","post":"吧。","options":["把行李放到房间里","放行李到房间里把","把放行李到房间里"],"answer":0,"explanation":"到 + nơi chốn chỉ đích đến."},{"context":"Phủ định: “Tôi chưa đưa sách cho anh ấy.”","pre":"我","blank":"没把书给他","post":"。","options":["没把书给他","把书没给他","把没书给他"],"answer":0,"explanation":"没 đứng trước 把."},{"context":"“Xin viết tên bạn lên đây.”","pre":"请","blank":"把你的名字写在这儿","post":"。","options":["把你的名字写在这儿","写你的名字在这儿","把写你的名字这儿"],"answer":0,"explanation":"把 + vật + 写 + 在 + nơi chốn."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我放书在桌子上。","isCorrect":false,"correctVersion":"我把书放在桌子上。","explanation":"Nêu đích đến của vật thì dùng câu chữ 把."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"请把你的名字写在这儿。","isCorrect":true,"explanation":"把 + vật + V + 在 + nơi chốn — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把书放桌子上在。","isCorrect":false,"correctVersion":"我把书放在桌子上。","explanation":"在 + nơi chốn đứng ngay sau động từ."},{"type":"sort","context":"Sắp xếp: “Tôi đặt quyển sách lên bàn rồi.”","words":["我","把","书","放","在","桌子","上","了","。"],"answer":"我把书放在桌子上了。","explanation":"把 + vật + 放在 + nơi chốn + 了."},{"type":"sort","context":"Sắp xếp: “Xin viết tên bạn vào đây.”","words":["请","把","你","的","名字","写","在","这儿","。"],"answer":"请把你的名字写在这儿。","explanation":"Câu đề nghị với 把."},{"type":"sort","context":"Sắp xếp: “Tôi đưa quyển sách đó cho cô ấy rồi.”","words":["我","把","那","本","书","给","她","了","。"],"answer":"我把那本书给她了。","explanation":"把 + vật + 给 + người + 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Tôi để điện thoại trên bàn rồi.","answer":"我把手机放在桌子上了。","answerPy":"Wǒ bǎ shǒujī fàng zài zhuōzi shàng le.","explanation":"把 + vật + 放在 + nơi chốn."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Bạn đưa quyển sách này cho thầy nhé.","answer":"你把这本书给老师吧。","answerPy":"Nǐ bǎ zhè běn shū gěi lǎoshī ba.","explanation":"把 + vật + 给 + người + 吧."}]}]});
